from pathlib import Path
import re

S = Path(r"D:\TigerIQ\Apps\DeXCamPersonal\Staged_v1_0_73_TEST_314_MCP")
res = S / "res/values/strings.xml"
txt = res.read_text(encoding="utf-8")

targets = [
    "Phương tiện", "Thông số", "CHỖ ĐỨNG", "Dãy thông tin",
    "ẢNH NỀN", "XE KHI ĐỖ", "Hồ sơ người lái", "racing"
]

found = {}
for line in txt.splitlines():
    for t in targets:
        if t.lower() in line.lower():
            m = re.search(r'name="([^"]+)"', line)
            if m:
                found[m.group(1)] = line.strip()

for k, v in found.items():
    print(f"{k}: {v}")

from pathlib import Path

S = Path(r"D:\TigerIQ\Apps\DeXCamPersonal\Staged_v1_0_73_TEST_314_MCP")
pub = S / "res/values/public.xml"

ids = {}
for line in pub.read_text(encoding="utf-8").splitlines():
    if any(k in line for k in ["tab_vehicle", "tab_params", "panel_layout_title", "road_tune_car_parked_title"]):
        print(line.strip())
        import re
        m = re.search(r'name="([^"]+)".*id="([^"]+)"', line)
        if m:
            ids[m.group(1)] = m.group(2)

print("IDs:", ids)
smali_dir = S / "smali"
for p in smali_dir.rglob("*.smali"):
    txt = p.read_text(encoding="utf-8")
    for name, hex_id in ids.items():
        if hex_id in txt:
            print(f"{name} ({hex_id}) used in {p.name}")

