from pathlib import Path
import re

p = Path(r"D:\TigerIQ\Apps\DeXCamPersonal\Staged_v1_0_73_TEST_314_MCP\smali\lw3.smali")
txt = p.read_text(encoding="utf-8")

pub_p = Path(r"D:\TigerIQ\Apps\DeXCamPersonal\Staged_v1_0_73_TEST_314_MCP\res\values\public.xml")
res_map = {}
for line in pub_p.read_text(encoding="utf-8").splitlines():
    m = re.search(r'type="string" name="([^"]+)".*id="([^"]+)"', line)
    if m:
        res_map[m.group(2)] = m.group(1)

for m in re.finditer(r'"([^"]+)"|0x7f11[0-9a-f]{4}', txt):
    s = m.group(0)
    if s.startswith("0x7f11"):
        print(s, res_map.get(s, "?"))
    else:
        print(s)

