package com.tigeriq.v75;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Context;
import android.content.DialogInterface;
import android.content.SharedPreferences;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.os.Handler;
import android.os.Looper;
import android.util.Log;
import android.view.Gravity;
import android.view.View;
import android.view.ViewGroup;
import android.widget.FrameLayout;
import android.widget.TextView;
import android.widget.Toast;
import java.lang.reflect.Field;
import java.lang.reflect.Method;

public final class FeatureSwitches {
    private static final String TAG = "TigerIQ-V75-Switches";
    private static final String PREF_NAME = "tigeriq_v75_features";
    public static final String KEY_RACING = "switch_racing_mode";
    public static final String KEY_WEATHER = "switch_weather_datetime";
    public static final String KEY_GPS = "switch_gps_speed";

    private static TextView switchButton;
    private static Activity currentActivity;

    private FeatureSwitches() {}

    public static Context getContext() {
        try {
            Class<?> bridge = Class.forName("com.tigeriq.v44.V44UiBridge");
            Object act = bridge.getMethod("getActivity").invoke(null);
            if (act instanceof Activity) return (Activity) act;
        } catch (Throwable ignored) {}
        try {
            Class<?> bridge = Class.forName("com.ultracar.dexsplit.ui.TigerIQBridge");
            Field f = bridge.getDeclaredField("sInstance");
            f.setAccessible(true);
            Object act = f.get(null);
            if (act instanceof Activity) return (Activity) act;
        } catch (Throwable ignored) {}
        return null;
    }

    private static SharedPreferences getPrefs() {
        Context c = getContext();
        if (c == null) return null;
        return c.getSharedPreferences(PREF_NAME, Context.MODE_PRIVATE);
    }

    public static boolean isRacingModeEnabled() {
        try {
            SharedPreferences p = getPrefs();
            return p == null || p.getBoolean(KEY_RACING, true);
        } catch (Throwable t) { return true; }
    }

    public static boolean isWeatherDateEnabled() {
        try {
            SharedPreferences p = getPrefs();
            return p == null || p.getBoolean(KEY_WEATHER, true);
        } catch (Throwable t) { return true; }
    }

    public static boolean isGpsSpeedEnabled() {
        try {
            SharedPreferences p = getPrefs();
            return p == null || p.getBoolean(KEY_GPS, true);
        } catch (Throwable t) { return true; }
    }

    public static void setRacingMode(boolean enabled) {
        try {
            SharedPreferences p = getPrefs();
            if (p != null) p.edit().putBoolean(KEY_RACING, enabled).commit();
        } catch (Throwable ignored) {}
    }

    public static void setWeatherDate(boolean enabled) {
        try {
            SharedPreferences p = getPrefs();
            if (p != null) p.edit().putBoolean(KEY_WEATHER, enabled).commit();
        } catch (Throwable ignored) {}
    }

    public static void setGpsSpeed(boolean enabled) {
        try {
            SharedPreferences p = getPrefs();
            if (p != null) p.edit().putBoolean(KEY_GPS, enabled).commit();
        } catch (Throwable ignored) {}
    }

    public static void showControl() {
        final Context c = getContext();
        if (!(c instanceof Activity)) return;
        final Activity a = (Activity) c;
        if (a.isFinishing()) return;

        a.runOnUiThread(new Runnable() {
            @Override
            public void run() {
                if (a.isFinishing()) return;
                FrameLayout root = (FrameLayout) a.findViewById(android.R.id.content);
                if (root == null) return;
                if (currentActivity != a || switchButton == null || switchButton.getParent() != root) {
                    if (switchButton != null && switchButton.getParent() instanceof ViewGroup) {
                        ((ViewGroup) switchButton.getParent()).removeView(switchButton);
                    }
                    currentActivity = a;
                    TextView btn = new TextView(a);
                    btn.setText("\u2699 B\u1eacT/T\u1eaeT T\u00cdNH N\u0102NG");
                    btn.setTextSize(13);
                    btn.setTextColor(Color.WHITE);
                    btn.setGravity(Gravity.CENTER);
                    btn.setAllCaps(false);

                    GradientDrawable bg = new GradientDrawable();
                    bg.setColor(0xff1e293b);
                    bg.setCornerRadius(dp(a, 8));
                    bg.setStroke(dp(a, 1.5f), 0xfff97316);
                    btn.setBackground(bg);
                    btn.setElevation(dp(a, 12));

                    FrameLayout.LayoutParams lp = new FrameLayout.LayoutParams(
                        dp(a, 180), dp(a, 38), Gravity.TOP | Gravity.RIGHT);
                    lp.rightMargin = dp(a, 200);
                    lp.topMargin = dp(a, 10);
                    root.addView(btn, lp);

                    btn.setOnClickListener(new View.OnClickListener() {
                        @Override
                        public void onClick(View v) {
                            openFeatureDialog(a);
                        }
                    });
                    switchButton = btn;
                }
                switchButton.setVisibility(View.VISIBLE);
                switchButton.bringToFront();
            }
        });
    }

    public static void hideControl() {
        if (currentActivity != null && switchButton != null) {
            currentActivity.runOnUiThread(new Runnable() {
                @Override
                public void run() {
                    if (switchButton != null) switchButton.setVisibility(View.GONE);
                }
            });
        }
    }

    public static void openFeatureDialog(final Activity a) {
        final String[] items = new String[] {
            "1. Racing mode (P RACING)",
            "2. Th\u1eddi ti\u1ebft, ng\u00e0y gi\u1edd",
            "3. T\u1ed1c \u0111\u1ed9 GPS (km/h)"
        };
        final boolean[] checked = new boolean[] {
            isRacingModeEnabled(),
            isWeatherDateEnabled(),
            isGpsSpeedEnabled()
        };

        AlertDialog.Builder builder = new AlertDialog.Builder(a);
        builder.setTitle("T\u00d9Y CH\u1eccN T\u1eaeT / M\u1ede T\u00cdNH N\u0102NG");
        builder.setMultiChoiceItems(items, checked, new DialogInterface.OnMultiChoiceClickListener() {
            @Override
            public void onClick(DialogInterface dialog, int which, boolean isChecked) {
                checked[which] = isChecked;
            }
        });
        builder.setPositiveButton("\u00c1p d\u1ee5ng & L\u01b0u", new DialogInterface.OnClickListener() {
            @Override
            public void onClick(DialogInterface dialog, int which) {
                setRacingMode(checked[0]);
                setWeatherDate(checked[1]);
                setGpsSpeed(checked[2]);
                Toast.makeText(a, "\u0110\u00e3 c\u1eadp nh\u1eadt c\u00e0i \u0111\u1eb7t t\u00ednh n\u0103ng!", Toast.LENGTH_SHORT).show();
                a.recreate();
            }
        });
        builder.setNegativeButton("H\u1ee7y", null);
        builder.show();
    }

    private static int dp(Context c, float d) {
        return (int) (c.getResources().getDisplayMetrics().density * d + 0.5f);
    }
}

