        bg.setColor(0xEE12151B); // Dark slate glass 93%
        bg.setCornerRadius(dp(context, 8f)); // Bo góc nhẹ 8dp
        barView.setBackground(bg);

        // Thu gọn padding tối đa: chỉ 2dp
        int pad = dp(context, 2f);
        barView.setPadding(pad, pad, pad, pad);
        barView.setOnTouchListener(createDragListener(context));

        // 1. Cụm điều khiển (Grip kéo thả lớn + Nút xoay 4 hướng)
        // Luôn thống nhất: Grip ở mép ngoài cùng, Rotate nằm liền kề bên trong
        LinearLayout controlCluster = new LinearLayout(context);
        controlCluster.setOrientation(isVertical ? LinearLayout.VERTICAL : LinearLayout.HORIZONTAL);
        controlCluster.setGravity(Gravity.CENTER);

        TextView grip = new TextView(context);
        grip.setText("\\u283F"); // Braille ⠿ grip lớn
        grip.setTextColor(0xFFFFFFFF);
        grip.setTextSize(20f);
        grip.setGravity(Gravity.CENTER);

        int gripW = isVertical ? dp(context, 34f) : dp(context, 24f);
        int gripH = isVertical ? dp(context, 24f) : dp(context, 34f);
        LinearLayout.LayoutParams gripLp = new LinearLayout.LayoutParams(gripW, gripH);
        grip.setLayoutParams(gripLp);
        grip.setOnTouchListener(createDragListener(context));

        TextView rotateBtn = new TextView(context);
        rotateBtn.setText("\\u27F3"); // ⟳
        rotateBtn.setTextColor(0xDDFFFFFF);
        rotateBtn.setTextSize(17f);
        rotateBtn.setGravity(Gravity.CENTER);

        int rotW = isVertical ? dp(context, 34f) : dp(context, 24f);
        int rotH = isVertical ? dp(context, 24f) : dp(context, 34f);
        LinearLayout.LayoutParams rotLp = new LinearLayout.LayoutParams(rotW, rotH);
        rotateBtn.setLayoutParams(rotLp);
        rotateBtn.setClickable(true);
        rotateBtn.setFocusable(true);
        rotateBtn.setOnClickListener(v -> rotate4Directions(context));

        if (!isReverse) {
            // Xuôi: Grip ở mép đầu, Rotate liền kề bên trong
            controlCluster.addView(grip);
            controlCluster.addView(rotateBtn);
        } else {
            // Ngược: Rotate bên trong, Grip ở mép đuôi ngoài cùng
            controlCluster.addView(rotateBtn);
            controlCluster.addView(grip);
        }

        // 2. Nút "+" để thêm bố cục mới vào thanh nổi
        FrameLayout addFrame = new FrameLayout(context);
        addFrame.setBackground(null);
        int slotSize = dp(context, 36f); // Vừa vặn 36dp
        int iconSize = dp(context, 32f); // Icon lớn 32dp

        TextView addTv = new TextView(context);
        addTv.setText("+");
        addTv.setTextSize(20f);
        addTv.setTextColor(0x88FFFFFF);
        addTv.setGravity(Gravity.CENTER);
        addFrame.addView(addTv, new FrameLayout.LayoutParams(
                FrameLayout.LayoutParams.MATCH_PARENT, FrameLayout.LayoutParams.MATCH_PARENT, Gravity.CENTER));

        addFrame.setClickable(true);
        addFrame.setFocusable(true);
        addFrame.setOnClickListener(v -> showAddDialog(context));
        LinearLayout.LayoutParams addLp = new LinearLayout.LayoutParams(slotSize, slotSize);
        addFrame.setLayoutParams(addLp);

        // 3. Danh sách các Slot động
        List<View> slotViews = new ArrayList<>();
        for (int i = 0; i < currentSlots.size(); i++) {
            final int slotIndex = i;
            final String sessionId = currentSlots.get(i);

            FrameLayout slotFrame = new FrameLayout(context);
            slotFrame.setBackground(null); // Bỏ viền bo góc bên trong

            ImageView iv = new ImageView(context);
            iv.setScaleType(ImageView.ScaleType.FIT_CENTER);
            Bitmap bmp = getIconForSession(sessionId);
            if (bmp != null) {
                iv.setImageBitmap(bmp);
            }
            FrameLayout.LayoutParams ivLp = new FrameLayout.LayoutParams(iconSize, iconSize, Gravity.CENTER);
            slotFrame.addView(iv, ivLp);

            slotFrame.setClickable(true);
            slotFrame.setFocusable(true);
            slotFrame.setOnClickListener(v -> {
                new Handler(Looper.getMainLooper()).post(() -> V44UiBridge.launchSession(sessionId));
            });
            slotFrame.setOnLongClickListener(v -> {
                new Handler(Looper.getMainLooper()).post(() -> showSlotOptionsDialog(context, slotIndex));
                return true;
            });

            LinearLayout.LayoutParams sLp = new LinearLayout.LayoutParams(slotSize, slotSize);
            int sm = dp(context, 1f); // Khoảng cách nhỏ 1dp
            if (isVertical) {
                sLp.setMargins(0, sm, 0, sm);
            } else {
                sLp.setMargins(sm, 0, sm, 0);
            }
            slotFrame.setLayoutParams(sLp);
            slotViews.add(slotFrame);
        }

        // 4. Lắp ghép vào barView theo hướng
        if (!isReverse) {
            // Direction 0 hoặc 1: Control (Grip -> Rotate) -> Slots -> Nút "+"
            barView.addView(controlCluster);
            for (View sv : slotViews) {
                barView.addView(sv);
            }
            barView.addView(addFrame);
        } else {
            // Direction 2 hoặc 3: Nút "+" -> Slots ngược -> Control (Rotate -> Grip)
            barView.addView(addFrame);
            for (int i = slotViews.size() - 1; i >= 0; i--) {
                barView.addView(slotViews.get(i));
            }
            barView.addView(controlCluster);
        }
    }

    private static void showAddDialog(Context context) {
        Activity act = V44UiBridge.getActivity();
        Context ctx = act != null ? act : context;
        List<Object> allSessions = V44UiBridge.sessions();
        if (allSessions.isEmpty()) {
            Toast.makeText(ctx, "Chưa có bố cục nào được lưu trong UltraCar", Toast.LENGTH_SHORT).show();
            return;
        }

        List<String> names = new ArrayList<>();
        List<String> ids = new ArrayList<>();
        for (Object s : allSessions) {
            String id = V44UiBridge.id(s);
            String name = V44UiBridge.name(s);
            if (!id.isEmpty()) {
                names.add(name.isEmpty() ? id : name);
                ids.add(id);
            }
        }

        AlertDialog.Builder builder = new AlertDialog.Builder(ctx);
        builder.setTitle("Thêm phím tắt vào thanh nổi");
        builder.setItems(names.toArray(new String[0]), (d, which) -> {
            String chosenId = ids.get(which);
            currentSlots.add(chosenId);
            saveSlots(context, currentSlots);
            rebuildBar(context);
        });
        builder.setNegativeButton("Hủy", null);
        AlertDialog dialog = builder.create();
        if (act == null) {
            dialog.getWindow().setType(WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY);
        }
        dialog.show();
    }

    private static void showSlotOptionsDialog(Context context, int index) {
        if (index < 0 || index >= currentSlots.size()) return;
        Activity act = V44UiBridge.getActivity();
        Context ctx = act != null ? act : context;
        String currentId = currentSlots.get(index);
        String currentName = getNameForSession(currentId);

        String[] options = new String[] { "Đổi bố cục khác", "Xóa nút này khỏi thanh nổi", "Hủy" };
        AlertDialog.Builder builder = new AlertDialog.Builder(ctx);
        builder.setTitle(currentName.isEmpty() ? "Tùy chọn phím tắt" : currentName);
        builder.setItems(options, (d, which) -> {
            if (which == 0) {
                showReplaceDialog(context, index);
            } else if (which == 1) {
                currentSlots.remove(index);
                saveSlots(context, currentSlots);
                rebuildBar(context);
            }
        });
        AlertDialog dialog = builder.create();
        if (act == null) {
            dialog.getWindow().setType(WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY);
        }
        dialog.show();
    }

    private static void showReplaceDialog(Context context, int index) {
        Activity act = V44UiBridge.getActivity();
        Context ctx = act != null ? act : context;
        List<Object> allSessions = V44UiBridge.sessions();
        if (allSessions.isEmpty()) return;

        List<String> names = new ArrayList<>();
        List<String> ids = new ArrayList<>();
        for (Object s : allSessions) {
            String id = V44UiBridge.id(s);
            String name = V44UiBridge.name(s);
            if (!id.isEmpty()) {
                names.add(name.isEmpty() ? id : name);
                ids.add(id);
            }
        }

        AlertDialog.Builder builder = new AlertDialog.Builder(ctx);
        builder.setTitle("Chọn bố cục thay thế");
        builder.setItems(names.toArray(new String[0]), (d, which) -> {
            String chosenId = ids.get(which);
            if (index >= 0 && index < currentSlots.size()) {
                currentSlots.set(index, chosenId);
                saveSlots(context, currentSlots);
                rebuildBar(context);
            }
        });
        builder.setNegativeButton("Hủy", null);
        AlertDialog dialog = builder.create();
        if (act == null) {
            dialog.getWindow().setType(WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY);
        }
        dialog.show();
    }

    private static View.OnTouchListener createDragListener(Context context) {
        return (v, event) -> {
            if (params == null || windowManager == null || barView == null) return false;
            switch (event.getActionMasked()) {
                case MotionEvent.ACTION_DOWN:
                    touchStartX = event.getRawX();
                    touchStartY = event.getRawY();
                    initialParamsX = params.x;
                    initialParamsY = params.y;
                    isDragging = false;
                    return true;
                case MotionEvent.ACTION_MOVE:
                    float dx = event.getRawX() - touchStartX;
                    float dy = event.getRawY() - touchStartY;
                    if (!isDragging && (Math.abs(dx) > 6 || Math.abs(dy) > 6)) {
                        isDragging = true;
                    }
                    if (isDragging) {
                        params.x = initialParamsX + (int) dx;
                        params.y = initialParamsY + (int) dy;
                        try {
                            windowManager.updateViewLayout(barView, params);
                        } catch (Throwable ignored) {}
                    }
                    return true;
                case MotionEvent.ACTION_UP:
                case MotionEvent.ACTION_CANCEL:
                    if (isDragging) {
                        savePosition(context, params.x, params.y);
                    }
                    return true;
            }
            return false;
        };
    }

    private static void savePosition(Context context, int x, int y) {
        if (context == null) return;
        try {
            SharedPreferences.Editor ed = context.getSharedPreferences("tigeriq_floating_bar", Context.MODE_PRIVATE).edit();
            ed.putInt("pos_x", x);
            ed.putInt("pos_y", y);
            ed.apply();
        } catch (Throwable ignored) {}
    }

    private static void saveDirection(Context context, int dir) {
        if (context == null) return;
        try {
            SharedPreferences.Editor ed = context.getSharedPreferences("tigeriq_floating_bar", Context.MODE_PRIVATE).edit();
            ed.putInt("bar_direction", dir);
            ed.apply();
        } catch (Throwable ignored) {}
    }
}
