code = '''package com.tigeriq.v44;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Context;
import android.content.SharedPreferences;
import android.graphics.Bitmap;
import android.graphics.Color;
import android.graphics.PixelFormat;
import android.graphics.drawable.Drawable;
import android.graphics.drawable.GradientDrawable;
import android.os.Handler;
import android.os.Looper;
import android.view.Gravity;
import android.view.MotionEvent;
import android.view.View;
import android.view.WindowManager;
import android.widget.FrameLayout;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.TextView;
import android.widget.Toast;

import java.util.ArrayList;
import java.util.List;

public final class FloatingQuickBar {
    private static WindowManager windowManager;
    private static LinearLayout barView;
    private static WindowManager.LayoutParams params;
    private static Context appContext;

    // Dynamic slots list
    private static final List<String> currentSlots = new ArrayList<>();

    // Orientation: 0 = Vertical (Doc), 1 = Horizontal (Ngang)
    private static int direction = 0;

    private static float touchStartX;
    private static float touchStartY;
    private static int initialParamsX;
    private static int initialParamsY;
    private static boolean isDragging = false;

    private FloatingQuickBar() {}

    private static int dp(Context ctx, float value) {
        if (ctx == null) return (int) value;
        return (int) (ctx.getResources().getDisplayMetrics().density * value + 0.5f);
    }

    public static synchronized void update(Context context, WindowManager wm) {
        if (context == null || wm == null) return;
        appContext = context.getApplicationContext() != null ? context.getApplicationContext() : context;
        remove();
        windowManager = wm;

        Handler mainHandler = new Handler(Looper.getMainLooper());
        mainHandler.post(() -> {
            try {
                loadSlots(context);
                createView(context);
                if (barView != null && windowManager != null) {
                    windowManager.addView(barView, params);
                }
            } catch (Throwable t) {
                t.printStackTrace();
            }
        });
    }

    public static synchronized void remove() {
        if (windowManager != null && barView != null) {
            try {
                windowManager.removeView(barView);
            } catch (Throwable ignored) {}
            barView = null;
        }
    }

    public static void refresh() {
        Handler mainHandler = new Handler(Looper.getMainLooper());
        mainHandler.post(() -> {
            if (appContext != null) {
                rebuildBar(appContext);
            }
        });
    }

    private static void loadSlots(Context context) {
        currentSlots.clear();
        SharedPreferences sp = context.getSharedPreferences(\"tigeriq_floating_bar\", Context.MODE_PRIVATE);
        String raw = sp.getString(\"custom_slots\", null);
        if (raw != null) {
            for (String s : raw.split(\",\")) {
                s = s.trim();
                if (!s.isEmpty()) currentSlots.add(s);
            }
        } else {
            // Default: import from V44UiBridge slots or sessions
            SharedPreferences vPrefs = context.getSharedPreferences(\"v44_ui\", Context.MODE_PRIVATE);
            for (int i = 0; i < 5; i++) {
                String s = vPrefs.getString(\"slot_\" + i, \"\");
                if (s != null && !s.trim().isEmpty()) {
                    currentSlots.add(s.trim());
                }
            }
            if (currentSlots.isEmpty()) {
                List<Object> allSessions = V44UiBridge.sessions();
                for (int i = 0; i < Math.min(5, allSessions.size()); i++) {
                    String id = V44UiBridge.id(allSessions.get(i));
                    if (!id.isEmpty()) currentSlots.add(id);
                }
            }
            saveSlots(context, currentSlots);
        }
    }

    private static void saveSlots(Context context, List<String> list) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < list.size(); i++) {
            if (i > 0) sb.append(\",\");
            sb.append(list.get(i));
        }
        context.getSharedPreferences(\"tigeriq_floating_bar\", Context.MODE_PRIVATE)
                .edit().putString(\"custom_slots\", sb.toString()).apply();
    }

    private static Bitmap getIconForSession(String sessionId) {
        if (sessionId == null || sessionId.isEmpty()) return null;
        for (Object s : V44UiBridge.sessions()) {
            if (sessionId.equals(V44UiBridge.id(s))) {
                Drawable d = V44UiBridge.icon(s);
                if (d != null) {
                    return V44UiBridge.drawableToBitmap(d);
                }
            }
        }
        return null;
    }

    private static String getNameForSession(String sessionId) {
        if (sessionId == null || sessionId.isEmpty()) return \"\";
        for (Object s : V44UiBridge.sessions()) {
            if (sessionId.equals(V44UiBridge.id(s))) {
                return V44UiBridge.name(s);
            }
        }
        return sessionId;
    }

    private static void toggleOrientation(Context context) {
        direction = (direction == 0) ? 1 : 0;
        saveDirection(context, direction);
        rebuildBar(context);
    }

    private static void rebuildBar(Context context) {
        if (barView != null && windowManager != null) {
            barView.removeAllViews();
            setupBarViews(context);
            try {
                windowManager.updateViewLayout(barView, params);
            } catch (Throwable ignored) {}
        }
    }

    private static void createView(Context context) {
        SharedPreferences sp = context.getSharedPreferences(\"tigeriq_floating_bar\", Context.MODE_PRIVATE);
        direction = sp.getInt(\"bar_direction\", 0);
        if (direction != 0 && direction != 1) direction = 0;

        barView = new LinearLayout(context);
        setupBarViews(context);

        params = new WindowManager.LayoutParams(
                WindowManager.LayoutParams.WRAP_CONTENT,
                WindowManager.LayoutParams.WRAP_CONTENT,
                WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,
                WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE
                        | WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS
                        | WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,
                PixelFormat.TRANSLUCENT
        );
        params.gravity = Gravity.TOP | Gravity.START;

        params.x = sp.getInt(\"pos_x\", dp(context, 10f));
        params.y = sp.getInt(\"pos_y\", dp(context, 200f));
    }

    private static void setupBarViews(Context context) {
        boolean isVertical = (direction == 0);

        barView.setOrientation(isVertical ? LinearLayout.VERTICAL : LinearLayout.HORIZONTAL);
        barView.setGravity(Gravity.CENTER);

        // Nền mờ sang trọng, bo góc nhẹ 6dp, BỎ TOÀN BỘ VIỀN NGOÀI (không stroke)
        GradientDrawable bg = new GradientDrawable();
        bg.setColor(0xDD12151B); // 87% dark glass
        bg.setCornerRadius(dp(context, 6f));
        barView.setBackground(bg);

        // Thu gọn padding tối đa: chỉ 1dp để không che nội dung màn hình
        int pad = dp(context, 1f);
        barView.setPadding(pad, pad, pad, pad);
        barView.setOnTouchListener(createDragListener(context));

        // 1. CỤM ĐIỀU KHIỂN THỐNG NHẤT:
        // Luôn luôn: Grip ngoài cùng mép đầu -> Rotate liền kề bên trong
        LinearLayout controlCluster = new LinearLayout(context);
        controlCluster.setOrientation(isVertical ? LinearLayout.VERTICAL : LinearLayout.HORIZONTAL);
        controlCluster.setGravity(Gravity.CENTER);

        // Nút kéo thả Grip (⠿)
        TextView grip = new TextView(context);
        grip.setText(\"\\u283F\"); // Braille ⠿
        grip.setTextColor(0xFFFFFFFF);
        grip.setTextSize(18f);
        grip.setGravity(Gravity.CENTER);

        int gripW = isVertical ? dp(context, 34f) : dp(context, 22f);
        int gripH = isVertical ? dp(context, 22f) : dp(context, 34f);
        LinearLayout.LayoutParams gripLp = new LinearLayout.LayoutParams(gripW, gripH);
        grip.setLayoutParams(gripLp);
        grip.setOnTouchListener(createDragListener(context));

        // Nút xoay (⟳)
        TextView rotateBtn = new TextView(context);
        rotateBtn.setText(\"\\u27F3\"); // ⟳
        rotateBtn.setTextColor(0xDDFFFFFF);
        rotateBtn.setTextSize(16f);
        rotateBtn.setGravity(Gravity.CENTER);

        int rotW = isVertical ? dp(context, 34f) : dp(context, 24f);
        int rotH = isVertical ? dp(context, 24f) : dp(context, 34f);
        LinearLayout.LayoutParams rotLp = new LinearLayout.LayoutParams(rotW, rotH);
        rotateBtn.setLayoutParams(rotLp);
        rotateBtn.setClickable(true);
        rotateBtn.setFocusable(true);
        rotateBtn.setOnClickListener(v -> toggleOrientation(context));

        controlCluster.addView(grip);
        controlCluster.addView(rotateBtn);
        barView.addView(controlCluster);

        // 2. CÁC SLOT ICON ĐỘNG (Thứ tự luôn chuẩn, không bị đảo ngược)
        int slotSize = dp(context, 36f);
        int iconSize = dp(context, 33f);
        int marginPx = dp(context, 1f);

        for (int i = 0; i < currentSlots.size(); i++) {
            final int slotIndex = i;
            final String sessionId = currentSlots.get(i);

            FrameLayout slotFrame = new FrameLayout(context);
            slotFrame.setBackground(null); // Bỏ viền bo góc bên trong

            ImageView iv = new ImageView(context);
            Bitmap bm = getIconForSession(sessionId);
            if (bm != null) {
                iv.setImageBitmap(bm);
            } else {
                iv.setImageResource(android.R.drawable.sym_def_app_icon);
            }
            iv.setScaleType(ImageView.ScaleType.FIT_CENTER);

            FrameLayout.LayoutParams ivLp = new FrameLayout.LayoutParams(iconSize, iconSize, Gravity.CENTER);
            slotFrame.addView(iv, ivLp);

            slotFrame.setClickable(true);
            slotFrame.setFocusable(true);
            slotFrame.setOnClickListener(v -> {
                if (sessionId != null && !sessionId.isEmpty()) {
                    launchSession(context, sessionId);
                }
            });

            // Nhấn giữ để XÓA hoặc ĐỔI bố cục
            slotFrame.setOnLongClickListener(v -> {
                showSlotOptionsDialog(context, slotIndex, sessionId);
                return true;
            });

            LinearLayout.LayoutParams sLp = new LinearLayout.LayoutParams(slotSize, slotSize);
            if (isVertical) {
                sLp.setMargins(0, marginPx, 0, marginPx);
            } else {
                sLp.setMargins(marginPx, 0, marginPx, 0);
            }
            slotFrame.setLayoutParams(sLp);

            barView.addView(slotFrame);
        }

        // 3. NÚT \"+\" ĐỂ THÊM BỐ CỤC
        FrameLayout addFrame = new FrameLayout(context);
        addFrame.setBackground(null);

        TextView addTv = new TextView(context);
        addTv.setText(\"+\");
        addTv.setTextSize(20f);
        addTv.setTextColor(0x99FFFFFF);
        addTv.setGravity(Gravity.CENTER);
        addFrame.addView(addTv, new FrameLayout.LayoutParams(
                FrameLayout.LayoutParams.MATCH_PARENT, FrameLayout.LayoutParams.MATCH_PARENT, Gravity.CENTER));

        addFrame.setClickable(true);
        addFrame.setFocusable(true);
        addFrame.setOnClickListener(v -> showAddDialog(context));

        LinearLayout.LayoutParams addLp = new LinearLayout.LayoutParams(slotSize, slotSize);
        if (isVertical) {
            addLp.setMargins(0, marginPx, 0, 0);
        } else {
            addLp.setMargins(marginPx, 0, 0, 0);
        }
        addFrame.setLayoutParams(addLp);

        barView.addView(addFrame);
    }

    private static void showAddDialog(Context context) {
        Activity act = V44UiBridge.getActivity();
        Context ctx = act != null ? act : context;
        List<Object> allSessions = V44UiBridge.sessions();
        if (allSessions.isEmpty()) {
            Toast.makeText(ctx, \"Chưa có bố cục nào được lưu trong UltraCar\", Toast.LENGTH_SHORT).show();
            return;
        }

        List<String> names = new ArrayList<>();
        List<String> ids = new ArrayList<>();
        for (Object s : allSessions) {
            String id = V44UiBridge.id(s);
            String name = V44UiBridge.name(s);
            if (!id.isEmpty()) {
                names.add(name.isEmpty() ? id : name);
                ids.add(id);
            }
        }

        AlertDialog.Builder builder = new AlertDialog.Builder(ctx);
        builder.setTitle(\"Thêm phím tắt vào thanh nổi\");
        builder.setItems(names.toArray(new String[0]), (d, which) -> {
            String chosenId = ids.get(which);
            currentSlots.add(chosenId);
            saveSlots(context, currentSlots);
            rebuildBar(context);
        });
        builder.setNegativeButton(\"Hủy\", null);
        AlertDialog dialog = builder.create();
        if (act == null) {
            dialog.getWindow().setType(WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY);
        }
        dialog.show();
    }

    private static void showSlotOptionsDialog(Context context, int index, String sessionId) {
        Activity act = V44UiBridge.getActivity();
        Context ctx = act != null ? act : context;
        String curName = getNameForSession(sessionId);
        if (curName.isEmpty()) curName = \"Bố cục #\" + (index + 1);

        String[] options = new String[]{\"Đổi bố cục khác\", \"Xóa nút này khỏi thanh nổi\"};

        AlertDialog.Builder builder = new AlertDialog.Builder(ctx);
        builder.setTitle(curName);
        builder.setItems(options, (dialog, which) -> {
            if (which == 0) {
                showChooseReplacementDialog(context, index);
            } else if (which == 1) {
                if (index >= 0 && index < currentSlots.size()) {
                    currentSlots.remove(index);
                    saveSlots(context, currentSlots);
                    rebuildBar(context);
                    Toast.makeText(ctx, \"Đã xóa khỏi thanh nổi\", Toast.LENGTH_SHORT).show();
                }
            }
        });
        builder.setNegativeButton(\"Đóng\", null);
        AlertDialog d = builder.create();
        if (act == null) {
            d.getWindow().setType(WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY);
        }
        d.show();
    }

    private static void showChooseReplacementDialog(Context context, int index) {
        Activity act = V44UiBridge.getActivity();
        Context ctx = act != null ? act : context;
        List<Object> allSessions = V44UiBridge.sessions();
        if (allSessions.isEmpty()) {
            Toast.makeText(ctx, \"Chưa có bố cục nào trong UltraCar\", Toast.LENGTH_SHORT).show();
            return;
        }

        List<String> names = new ArrayList<>();
        List<String> ids = new ArrayList<>();
        for (Object s : allSessions) {
            String id = V44UiBridge.id(s);
            String name = V44UiBridge.name(s);
            if (!id.isEmpty()) {
                names.add(name.isEmpty() ? id : name);
                ids.add(id);
            }
        }

        AlertDialog.Builder builder = new AlertDialog.Builder(ctx);
        builder.setTitle(\"Chọn bố cục thay thế\");
        builder.setItems(names.toArray(new String[0]), (d, which) -> {
            String chosenId = ids.get(which);
