            iv.setScaleType(ImageView.ScaleType.FIT_CENTER);

            FrameLayout.LayoutParams ivLp = new FrameLayout.LayoutParams(iconSize, iconSize, Gravity.CENTER);
            slotFrame.addView(iv, ivLp);

            slotFrame.setClickable(true);
            slotFrame.setFocusable(true);
            slotFrame.setOnClickListener(v -> {
                if (sessionId != null && !sessionId.isEmpty()) {
                    launchSession(context, sessionId);
