    public static void launchSession(Context context, String sessionId) {
        if (sessionId == null || sessionId.trim().isEmpty()) return;
        try {
            Activity act = V44UiBridge.getActivity();
            if (act != null) {
                java.lang.reflect.Method mO = act.getClass().getMethod("o");
                Object vm = mO.invoke(act);
                if (vm != null) {
                    java.lang.reflect.Method mJ = vm.getClass().getMethod("j", String.class);
                    mJ.invoke(vm, sessionId);
                    return;
                }
            }
        } catch (Throwable ignored) {}

        // Fallback Intent
        try {
            Context ctx = context != null ? context : appContext;
            if (ctx != null) {
                android.content.Intent it = new android.content.Intent();
                it.setClassName(ctx.getPackageName(), "com.ultracar.dexsplit.ui.MainActivity");
                it.addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK | android.content.Intent.FLAG_ACTIVITY_SINGLE_TOP);
                it.putExtra("launch_session_id", sessionId);
                ctx.startActivity(it);
            }
        } catch (Throwable ignored) {}
    }

    private static View.OnTouchListener createDragListener(Context context) {
        return (v, event) -> {
            if (params == null || windowManager == null || barView == null) return false;
            switch (event.getActionMasked()) {
                case MotionEvent.ACTION_DOWN:
                    touchStartX = event.getRawX();
                    touchStartY = event.getRawY();
                    initialParamsX = params.x;
                    initialParamsY = params.y;
                    isDragging = false;
                    return true;
                case MotionEvent.ACTION_MOVE:
                    float dx = event.getRawX() - touchStartX;
                    float dy = event.getRawY() - touchStartY;
                    if (!isDragging && (Math.abs(dx) > 6 || Math.abs(dy) > 6)) {
                        isDragging = true;
                    }
                    if (isDragging) {
                        params.x = initialParamsX + (int) dx;
                        params.y = initialParamsY + (int) dy;
                        try {
                            windowManager.updateViewLayout(barView, params);
                        } catch (Throwable ignored) {}
                    }
                    return true;
                case MotionEvent.ACTION_UP:
                case MotionEvent.ACTION_CANCEL:
                    if (isDragging) {
                        savePosition(context, params.x, params.y);
                    }
                    return true;
            }
            return false;
        };
    }

    private static void savePosition(Context context, int x, int y) {
        if (context == null) return;
        try {
            SharedPreferences.Editor ed = context.getSharedPreferences("tigeriq_floating_bar", Context.MODE_PRIVATE).edit();
            ed.putInt("pos_x", x);
            ed.putInt("pos_y", y);
            ed.apply();
        } catch (Throwable ignored) {}
    }

    private static void saveDirection(Context context, int dir) {
        if (context == null) return;
        try {
            SharedPreferences.Editor ed = context.getSharedPreferences("tigeriq_floating_bar", Context.MODE_PRIVATE).edit();
            ed.putInt("bar_direction", dir);
            ed.apply();
        } catch (Throwable ignored) {}
    }
}

