package com.tigeriq.camera;

import android.content.Context;
import android.util.Log;
import com.ultracar.dexsplit.ui.MainActivity;

public class CameraBridge {
    private static final String TAG = "CameraBridge";
    public static boolean isCameraOpen = false;

    public static void openCamera() {
        try {
            isCameraOpen = true;
            Log.i(TAG, "Opening Camera Window...");
            MainActivity.openCameraWindow();
        } catch (Throwable t) {
            Log.e(TAG, "Failed to open camera window", t);
        }
    }

    public static void closeCamera() {
        try {
            isCameraOpen = false;
            Log.i(TAG, "Closing Camera Window...");
            MainActivity.closeCameraWindow();
        } catch (Throwable t) {
            Log.e(TAG, "Failed to close camera window", t);
        }
    }

    public static void toggleCamera() {
        if (isCameraOpen) {
            closeCamera();
        } else {
            openCamera();
        }
    }

    public static void onFloatingClick(Context context, long pressDuration) {
        if (pressDuration >= 500L) {
            Log.i(TAG, "Long-press detected (" + pressDuration + "ms) -> Opening Camera Settings");
            CameraSettingsActivity.launch(context);
        } else {
            Log.i(TAG, "Quick tap detected (" + pressDuration + "ms) -> Toggling Camera Window");
            toggleCamera();
        }
    }
}

