import java.lang.reflect.*;
import java.nio.ByteBuffer;

public class SignalProbe {
    static ByteBuffer makeFrame(int w, int h, int yBase, int yAmp, int uvVal) {
        int ySize = w * h;
        int uvSize = ySize / 2;
        ByteBuffer buf = ByteBuffer.allocateDirect(ySize + uvSize);
        for (int i = 0; i < ySize; i++) {
            int y = yBase + ((i * 37) % Math.max(1, yAmp * 2)) - yAmp;
            buf.put(i, (byte) Math.max(0, Math.min(255, y)));
        }
        for (int i = 0; i < uvSize; i++) {
            buf.put(ySize + i, (byte) uvVal);
        }
        buf.position(0);
        return buf;
    }

    public static void main(String[] args) throws Exception {
        Class<?> fz1Cls = Class.forName("fz1");
        Object fz1 = fz1Cls.getDeclaredConstructor().newInstance();
        Object cb = fz1Cls.getField("f").get(fz1);
        Method onFrame = cb.getClass().getMethod("onFrame", ByteBuffer.class);
        Field fb = fz1Cls.getField("b");
        Field fi = fz1Cls.getField("i");
        Field fk = fz1Cls.getField("k");
        Field fm = fz1Cls.getField("m");

        // 1. Feed 15 real signal frames (yAmp=40 -> stdDev ~ 23, uv=140 -> chroma=12)
        ByteBuffer realSig = makeFrame(640, 480, 120, 40, 140);
        for (int i = 0; i < 15; i++) {
            onFrame.invoke(cb, realSig);
        }
        System.out.println("After 15 real: b=" + fb.getInt(fz1) + " std=" + fi.getDouble(fz1) + " mean=" + fk.getDouble(fz1) + " m=" + fm.getDouble(fz1));

        // 2. Now shift to D -> feed black frame (stdDev ~ 0, uv=128)
        ByteBuffer black = makeFrame(640, 480, 16, 1, 128);
        onFrame.invoke(cb, black);
        System.out.println("After 1 black: b=" + fb.getInt(fz1) + " std=" + fi.getDouble(fz1) + " mean=" + fk.getDouble(fz1) + " m=" + fm.getDouble(fz1));

        // 3. Re-open with 15 real frames, then feed green static (yAmp=30, uv=0 -> chroma=128)
        for (int i = 0; i < 15; i++) onFrame.invoke(cb, realSig);
        System.out.println("Reopened real: b=" + fb.getInt(fz1));
        ByteBuffer greenStatic = makeFrame(640, 480, 90, 30, 0);
        onFrame.invoke(cb, greenStatic);
        System.out.println("After 1 greenStatic: b=" + fb.getInt(fz1) + " std=" + fi.getDouble(fz1) + " m=" + fm.getDouble(fz1));

        // 4. Feed brake hum (yAmp=6 -> stdDev ~ 3.5)
        for (int i = 0; i < 20; i++) onFrame.invoke(cb, makeFrame(640, 480, 20, 6, 128));
        System.out.println("After 20 hum(amp6): b=" + fb.getInt(fz1) + " std=" + fi.getDouble(fz1));

        // 5. Feed short buffer
        for (int i = 0; i < 15; i++) onFrame.invoke(cb, realSig);
        onFrame.invoke(cb, ByteBuffer.allocateDirect(10));
        System.out.println("After short buf: b=" + fb.getInt(fz1));
    }
}

