import os
import shutil
import subprocess
import tempfile
import zipfile
import numpy as np
from PIL import Image

ADB = r"D:\TigerIQ\Apps\LAIXI-1.1.5.5\tools\platform-tools\adb.exe"
SERIAL = "R3CM400AKRX"
APK = r"D:\TigerIQ\Apps\DeXCamPersonal\Builds_v1201\UltraCar_v1.2.01.apk"
D8_BAT = r"D:\TigerIQ\Tools\AndroidBuildTools35\unpacked\android-15\d8.bat"
BRAIN_UPLOADS = r"C:\Users\wdragons12x\.gemini\antigravity\brain\f4cd40d1-845a-4965-95af-0b0d9fdfa6f1\.user_uploaded"

PROBE_JAVA = r"""
import java.io.File;
import java.io.FileInputStream;
import java.lang.reflect.Field;
import java.nio.ByteBuffer;

public class SignalProbe {
    static ByteBuffer load(String path) throws Exception {
        File f = new File(path);
        byte[] data = new byte[(int) f.length()];
        try (FileInputStream fis = new FileInputStream(f)) {
            int off = 0;
            while (off < data.length) {
                int r = fis.read(data, off, data.length - off);
                if (r < 0) break;
                off += r;
            }
        }
        return ByteBuffer.wrap(data);
    }

    static void feed(Object det, Object cb, ByteBuffer buf, int n) throws Exception {
        java.lang.reflect.Method onFrame = cb.getClass().getMethod("onFrame", ByteBuffer.class);
        for (int i = 0; i < n; i++) {
            buf.rewind();
            onFrame.invoke(cb, buf);
        }
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        Class<?> fz1Cls = Class.forName("fz1");
        Object det = fz1Cls.getConstructor().newInstance();
        Field fCb = fz1Cls.getField("f");
        Field fStreak = fz1Cls.getField("b");
        Field fStd = fz1Cls.getField("i");
        Field fMean = fz1Cls.getField("k");
        Field fChroma = fz1Cls.getField("m");
        Object cb = fCb.get(det);

        ByteBuffer realCam = load(dir + "/Photo3_real.nv21");
        ByteBuffer greenSnow = load(dir + "/Photo4_green.nv21");
        ByteBuffer black = load(dir + "/Syn_black.nv21");
        ByteBuffer blueNoise = load(dir + "/Syn_blue_noise.nv21");
        ByteBuffer noise4 = load(dir + "/Syn_noise_std4.nv21");
        ByteBuffer colorBars = load(dir + "/Syn_color_bars.nv21");
        ByteBuffer shortBuf = ByteBuffer.wrap(new byte[3]);

        // 1. Short buffer must fail closed and reset streak to 0
        fStreak.setInt(det, 5);
        feed(det, cb, shortBuf, 1);
        int s1 = fStreak.getInt(det);
        if (s1 != 0) throw new AssertionError("Short buffer streak=" + s1);
        System.out.println("CASE_1_SHORT_BUF: PASS streak=" + s1);

        // 2. Green static snow (Photo 4) 20 frames -> must reject (streak=0)
        feed(det, cb, greenSnow, 20);
        int s2 = fStreak.getInt(det);
        if (s2 != 0) throw new AssertionError("Photo4 green snow accepted! streak=" + s2 + " chroma=" + fChroma.getDouble(det));
        System.out.println(String.format("CASE_2_PHOTO4_GREEN: PASS streak=%d std=%.2f chroma=%.2f", s2, fStd.getDouble(det), fChroma.getDouble(det)));

        // 3. Blue noisy no-signal 20 frames -> must reject (streak=0)
        feed(det, cb, blueNoise, 20);
        int s3 = fStreak.getInt(det);
        if (s3 != 0) throw new AssertionError("Blue noise accepted! streak=" + s3 + " chroma=" + fChroma.getDouble(det));
        System.out.println(String.format("CASE_3_BLUE_NOISE: PASS streak=%d std=%.2f chroma=%.2f", s3, fStd.getDouble(det), fChroma.getDouble(det)));

        // 4. SMPTE color bars -> must reject (streak=0)
        feed(det, cb, colorBars, 20);
        int s4 = fStreak.getInt(det);
        if (s4 != 0) throw new AssertionError("Color bars accepted! streak=" + s4);
        System.out.println(String.format("CASE_4_COLOR_BARS: PASS streak=%d std=%.2f chroma=%.2f", s4, fStd.getDouble(det), fChroma.getDouble(det)));

        // 5. Low-luma noise std~4.0 (stop/brake glitch) 20 frames -> must reject (streak=0)
        feed(det, cb, noise4, 20);
        int s5 = fStreak.getInt(det);
        if (s5 != 0) throw new AssertionError("Noise std4 accepted! streak=" + s5 + " std=" + fStd.getDouble(det));
        System.out.println(String.format("CASE_5_NOISE_STD4: PASS streak=%d std=%.2f", s5, fStd.getDouble(det)));

        // 6. Real camera (Photo 3): 11 frames < 12, then 12th reaches streak=12
        feed(det, cb, realCam, 11);
        int s6a = fStreak.getInt(det);
        if (s6a != 11) throw new AssertionError("Expected 11 at frame 11, got " + s6a);
        feed(det, cb, realCam, 1);
        int s6b = fStreak.getInt(det);
        if (s6b != 12) throw new AssertionError("Expected 12 at frame 12, got " + s6b);
        System.out.println(String.format("CASE_6_REAL_CAM: PASS streak=%d mean=%.2f std=%.2f chroma=%.2f", s6b, fMean.getDouble(det), fStd.getDouble(det), fChroma.getDouble(det)));

        // 7. R -> D transition: Real cam streak=12 followed by 1 Photo4 green snow frame -> instant streak=0
        feed(det, cb, greenSnow, 1);
        int s7 = fStreak.getInt(det);
        if (s7 != 0) throw new AssertionError("R->D Photo4 green snow did not reset streak! streak=" + s7);
        System.out.println("CASE_7_R_TO_D_GREEN: PASS streak=" + s7);

        // 8. R -> D transition: Real cam streak=12 followed by 1 black frame -> instant streak=0
        feed(det, cb, realCam, 12);
        if (fStreak.getInt(det) != 12) throw new AssertionError("Failed to re-arm to 12");
        feed(det, cb, black, 1);
        int s8 = fStreak.getInt(det);
        if (s8 != 0) throw new AssertionError("R->D black did not reset streak! streak=" + s8);
        System.out.println("CASE_8_R_TO_D_BLACK: PASS streak=" + s8);

        System.out.println("ALL_ART_SIGNAL_PROBE_PASSED");
    }
}
"""


def image_to_nv21(rgb_arr):
    r, g, b = rgb_arr[:, :, 0], rgb_arr[:, :, 1], rgb_arr[:, :, 2]
    h, w = r.shape
    h2, w2 = (h // 2) * 2, (w // 2) * 2
    r, g, b = r[:h2, :w2], g[:h2, :w2], b[:h2, :w2]
    y = np.clip(np.round(0.299 * r + 0.587 * g + 0.114 * b), 0, 255).astype(np.uint8)
    rb = r.reshape(h2 // 2, 2, w2 // 2, 2).mean(axis=(1, 3))
    gb = g.reshape(h2 // 2, 2, w2 // 2, 2).mean(axis=(1, 3))
    bb = b.reshape(h2 // 2, 2, w2 // 2, 2).mean(axis=(1, 3))
    u = np.clip(np.round(-0.168736 * rb - 0.331264 * gb + 0.5 * bb + 128), 0, 255).astype(np.uint8)
    v = np.clip(np.round(0.5 * rb - 0.418688 * gb - 0.081312 * bb + 128), 0, 255).astype(np.uint8)
    vu = np.empty((h2 // 2, w2), dtype=np.uint8)
    vu[:, 0::2] = v
    vu[:, 1::2] = u
    return np.concatenate([y.ravel(), vu.ravel()])


def crop_nv21(img_path, box):
    im = Image.open(img_path).convert("RGB").resize((640, 480))
    w, h = im.size
    crop = im.crop((int(w * box[0]), int(h * box[1]), int(w * box[2]), int(h * box[3]))).resize((640, 480))
    return image_to_nv21(np.asarray(crop, dtype=np.float32))


def main():
    tmp = tempfile.mkdtemp()
    try:
        src_java = os.path.join(tmp, "SignalProbe.java")
        with open(src_java, "w", encoding="utf-8") as f:
            f.write(PROBE_JAVA)
        subprocess.check_call(["javac", "--release", "8", src_java], cwd=tmp)
        subprocess.check_call([D8_BAT, "--min-api", "26", "--output", tmp, os.path.join(tmp, "SignalProbe.class")], cwd=tmp)
        probe_dex = os.path.join(tmp, "classes.dex")
        probe_renamed = os.path.join(tmp, "probe.dex")
        os.rename(probe_dex, probe_renamed)

        app_dex = os.path.join(tmp, "app_classes.dex")
        with zipfile.ZipFile(APK) as z:
            with open(app_dex, "wb") as out_f:
                out_f.write(z.read("classes.dex"))

