import android.graphics.RectF;

public final class FloatingCarRearIcon {
    private FloatingCarRearIcon() {}

    public static void draw(Canvas canvas, Paint paint, int w, int h, boolean enabled) {
        if (w <= 0 || h <= 0) return;
        float wf = (float) w;
        float hf = (float) h;
        float cx = wf * 0.5f;
        float cy = hf * 0.5f;
        float minDim = Math.min(wf, hf);
        float radius = (minDim * 0.5f) - Math.max(4.0f, minDim * 0.032f);

        // 1. Circular dark backdrop
        paint.reset();
        paint.setAntiAlias(true);
        paint.setStyle(Paint.Style.FILL);
        paint.setColor(enabled ? 0xE60B2216 : 0xCC181C22);
        canvas.drawCircle(cx, cy, radius, paint);

        // 2. Circular outer ring (ON = bright green, OFF = neutral gray)
        paint.setStyle(Paint.Style.STROKE);
        paint.setColor(enabled ? 0xFF00E676 : 0xCC78828E);
        paint.setStrokeWidth(Math.max(3.5f, minDim * (enabled ? 0.045f : 0.032f)));
        canvas.drawCircle(cx, cy, radius, paint);

        // 3. Car rear view silhouette (shifted slightly left-down away from 'R' badge at top-right)
        float carCx = wf * 0.47f;
        float carTop = hf * 0.30f;
        float carBot = hf * 0.76f;
        float carH = carBot - carTop;
        float bodyW = wf * 0.54f;
        float roofW = wf * 0.36f;

        int bodyColor = enabled ? 0xFFFFFFFF : 0xBB9CA3AF;
        int wheelColor = enabled ? 0xFF07150E : 0xFF1F242B;
        int glassColor = enabled ? 0xFF102A1D : 0xFF282E36;
        int accentColor = enabled ? 0xFF00E676 : 0xFF6B7280;
        int accentCore = enabled ? 0xFFB9F6CA : 0xFF9CA3AF;

        // 3a. Rear tires (left and right)
        paint.setStyle(Paint.Style.FILL);
        paint.setColor(bodyColor);
        float tireW = bodyW * 0.19f;
        float tireH = carH * 0.24f;
        float tireTop = carBot - tireH * 0.72f;
        float leftEdge = carCx - bodyW * 0.46f;
        float rightEdge = carCx + bodyW * 0.46f;
        float tr = minDim * 0.03f;
        canvas.drawRoundRect(new RectF(leftEdge, tireTop, leftEdge + tireW, carBot + carH * 0.04f), tr, tr, paint);
        canvas.drawRoundRect(new RectF(rightEdge - tireW, tireTop, rightEdge, carBot + carH * 0.04f), tr, tr, paint);

        // 3b. Upper cabin trapezoid (roof + C-pillars)
        float waistY = carTop + carH * 0.42f;
        Path cabin = new Path();
        cabin.moveTo(carCx - roofW * 0.45f, carTop);
        cabin.lineTo(carCx + roofW * 0.45f, carTop);
        cabin.lineTo(carCx + bodyW * 0.44f, waistY + carH * 0.04f);
        cabin.lineTo(carCx - bodyW * 0.44f, waistY + carH * 0.04f);
        cabin.close();
        paint.setColor(bodyColor);
        canvas.drawPath(cabin, paint);

        // 3c. Rear windshield inside cabin
        Path glass = new Path();
        float gwTop = roofW * 0.36f;
        float gwBot = bodyW * 0.34f;
        glass.moveTo(carCx - gwTop, carTop + carH * 0.09f);
        glass.lineTo(carCx + gwTop, carTop + carH * 0.09f);
        glass.lineTo(carCx + gwBot, waistY - carH * 0.02f);
        glass.lineTo(carCx - gwBot, waistY - carH * 0.02f);
        glass.close();
        paint.setColor(glassColor);
        canvas.drawPath(glass, paint);

        // 3d. Lower wide rear body / bumper / tailgate
        RectF body = new RectF(
            carCx - bodyW * 0.50f,
            waistY,
            carCx + bodyW * 0.50f,
            carBot - carH * 0.12f
        );
        paint.setColor(bodyColor);
        canvas.drawRoundRect(body, minDim * 0.055f, minDim * 0.055f, paint);

        // 3e. Tail lights (bold horizontal-angled bars near top of rear tailgate)
        float lightTop = waistY + carH * 0.09f;
        float lightBot = waistY + carH * 0.22f;
        float lightOutX = bodyW * 0.44f;
        float lightInX = bodyW * 0.19f;
        float lr = minDim * 0.02f;
        paint.setColor(accentColor);
        canvas.drawRoundRect(new RectF(carCx - lightOutX, lightTop, carCx - lightInX, lightBot), lr, lr, paint);
        canvas.drawRoundRect(new RectF(carCx + lightInX, lightTop, carCx + lightOutX, lightBot), lr, lr, paint);

        paint.setColor(accentCore);
        float insetY = (lightBot - lightTop) * 0.25f;
        canvas.drawRoundRect(new RectF(carCx - lightOutX + minDim * 0.015f, lightTop + insetY, carCx - lightInX - minDim * 0.015f, lightBot - insetY), lr, lr, paint);
        canvas.drawRoundRect(new RectF(carCx + lightInX + minDim * 0.015f, lightTop + insetY, carCx + lightOutX - minDim * 0.015f, lightBot - insetY), lr, lr, paint);

