    replace_exact(p_yml, "  versionCode: '345'\n  versionName: 1.0.99", "  versionCode: '350'\n  versionName: 1.2.04")

    str_files = glob.glob(os.path.join(STAGE, "res", "values*", "strings.xml"))
    updated_strings = 0
    for sf in str_files:
        txt = open(sf, "r", encoding="utf-8").read()
        if "v1.0.99" in txt:
            replace_exact(sf, "v1.0.99", "v1.2.04")
            updated_strings += 1
    assert updated_strings == 7, f"Expected 7 strings.xml updates, got {updated_strings}"
    log(f"Updated v1.2.04 subtitle in {updated_strings} strings.xml files.")

    os.makedirs(BUILD_ROOT, exist_ok=True)
    unsigned_apk = os.path.join(BUILD_ROOT, "UltraCar_v1.2.04_unsigned.apk")
    aligned_apk = os.path.join(BUILD_ROOT, "UltraCar_v1.2.04_aligned.apk")
    signed_apk = os.path.join(BUILD_ROOT, FINAL_APK_NAME)
    for f in (unsigned_apk, aligned_apk, signed_apk, signed_apk + ".idsig"):
