static void flushViewPostQueue(View v) throws Throwable {
    java.lang.reflect.Field rqField = View.class.getDeclaredField("mRunQueue");
    rqField.setAccessible(true);
    Object q = rqField.get(v);
    if (q != null) {
        Method exec = q.getClass().getMethod("executeActions", Handler.class);
        exec.setAccessible(true);
        Handler h = new Handler(Looper.getMainLooper());
        exec.invoke(q, h);
        // Execute queued Runnables synchronously if posted directly to h:
        java.lang.reflect.Field fQueue = android.os.MessageQueue.class.getDeclaredField("mMessages");
        fQueue.setAccessible(true);
        android.os.Message msg = (android.os.Message) fQueue.get(Looper.myQueue());
        while (msg != null) {
            Runnable cb = msg.getCallback();
            if (cb != null) cb.run();
            java.lang.reflect.Field fNext = android.os.Message.class.getDeclaredField("next");
            fNext.setAccessible(true);
            msg = (android.os.Message) fNext.get(msg);
        }
    }
}

