import com.android.tools.smali.baksmali.Adaptors.ClassDefinition;
import com.android.tools.smali.baksmali.BaksmaliOptions;
import com.android.tools.smali.baksmali.formatter.BaksmaliWriter;
import com.android.tools.smali.dexlib2.DexFileFactory;
import com.android.tools.smali.dexlib2.dexbacked.DexBackedDexFile;
import com.android.tools.smali.dexlib2.iface.ClassDef;
import com.android.tools.smali.dexlib2.iface.MultiDexContainer;
import java.io.File;
import java.io.FileOutputStream;
import java.io.OutputStreamWriter;
import java.io.StringWriter;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class DexDiff {
    static Map<String, String> loadAll(File dexFile) throws Exception {
        MultiDexContainer container = DexFileFactory.loadDexContainer(dexFile, null);
        DexBackedDexFile dex = container.getEntry((String) container.getDexEntryNames().get(0)).getDexFile();
        BaksmaliOptions opts = new BaksmaliOptions();
        opts.localsDirective = false;
        Map<String, String> map = new TreeMap<>();
        int n = dex.classSection.size();
        for (int i = 0; i < n; i++) {
            ClassDef cls = (ClassDef) dex.classSection.get(i);
            StringWriter sw = new StringWriter(1024);
            try (BaksmaliWriter bw = new BaksmaliWriter(sw, cls.getType())) {
                new ClassDefinition(opts, cls).writeTo(bw);
            }
            map.put(cls.getType(), sw.toString());
        }
        return map;
    }

    public static void main(String[] args) throws Exception {
        Map<String, String> m1 = loadAll(new File(args[0]));
        Map<String, String> m2 = loadAll(new File(args[1]));
        File outDir = new File(args[2]);
        outDir.mkdirs();

        Set<String> all = new TreeSet<>();
        all.addAll(m1.keySet());
        all.addAll(m2.keySet());

        List<String> added = new ArrayList<>();
        List<String> removed = new ArrayList<>();
        List<String> changed = new ArrayList<>();

        for (String t : all) {
            String s1 = m1.get(t);
            String s2 = m2.get(t);
            if (s1 == null) {
                added.add(t);
            } else if (s2 == null) {
                removed.add(t);
            } else if (!s1.equals(s2)) {
                changed.add(t);
                String safe = t.substring(1, t.length() - 1).replace('/', '_').replace('$', '_');
                try (OutputStreamWriter w1 = new OutputStreamWriter(new FileOutputStream(new File(outDir, safe + ".old.smali")), StandardCharsets.UTF_8);
                     OutputStreamWriter w2 = new OutputStreamWriter(new FileOutputStream(new File(outDir, safe + ".new.smali")), StandardCharsets.UTF_8)) {
                    w1.write(s1);
                    w2.write(s2);
                }
            }
        }
        System.out.println("COUNTS v1203=" + m1.size() + " v1204=" + m2.size());
        System.out.println("ADDED (" + added.size() + "): " + added);
        System.out.println("REMOVED (" + removed.size() + "): " + removed);
        System.out.println("CHANGED (" + changed.size() + "): " + changed);
    }
}
"""


def main() -> None:
    tmp = tempfile.mkdtemp(prefix="dexdiff_fast_")
    try:
        java_path = os.path.join(tmp, "DexDiff.java")
        with open(java_path, "w", encoding="utf-8") as f:
            f.write(JAVA_DIFF)
        comp = subprocess.run(["javac", "-cp", APKTOOL_JAR, java_path], capture_output=True, text=True)
        if comp.returncode != 0:
            raise RuntimeError(f"javac failed:\n{comp.stderr}")

        dex3 = os.path.join(tmp, "v1203.dex")
        dex4 = os.path.join(tmp, "v1204.dex")
        with zipfile.ZipFile(APK_V1203, "r") as zf:
            with open(dex3, "wb") as f:
                f.write(zf.read("classes.dex"))
        with zipfile.ZipFile(APK_V1204, "r") as zf:
            with open(dex4, "wb") as f:
                f.write(zf.read("classes.dex"))

        diffs_dir = os.path.join(tmp, "diffs")
        res = subprocess.run(
            ["java", "-Xmx1024m", "-cp", APKTOOL_JAR + os.pathsep + tmp, "DexDiff", dex3, dex4, diffs_dir],
            capture_output=True,
            text=True,
            errors="replace",
        )
        if res.returncode != 0:
            raise RuntimeError(f"DexDiff failed:\n{res.stdout}\n{res.stderr}")
        print(res.stdout)

        for fn in sorted(os.listdir(diffs_dir)):
            if not fn.endswith(".old.smali"):
                continue
            base = fn[:-10]
            with open(os.path.join(diffs_dir, base + ".old.smali"), encoding="utf-8") as f:
                s1 = f.read().splitlines()
            with open(os.path.join(diffs_dir, base + ".new.smali"), encoding="utf-8") as f:
                s2 = f.read().splitlines()
            print("=" * 60)
            print("DIFF:", base)
            for line in difflib.unified_diff(s1, s2, fromfile="v1203/" + base, tofile="v1204/" + base, n=2):
                print(line)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


if __name__ == "__main__":
    main()

