import com.tigeriq.camera.GuideMotionHub;
import com.tigeriq.camera.MotionSteeringEstimator;
import com.tigeriq.camera.ReversePathGeometry;
import com.tigeriq.camera.UvcFrameSignalEvidence;
import java.nio.ByteBuffer;

public class GuideEngineUnitTest {
    private static void check(boolean cond, String msg) {
        if (!cond) {
            throw new AssertionError("FAIL: " + msg);
        }
    }

    private static void checkNear(double actual, double expected, double eps, String msg) {
        if (Math.abs(actual - expected) > eps) {
            throw new AssertionError("FAIL " + msg + ": expected=" + expected + " actual=" + actual);
        }
    }

    private static void testGeometryInvariants() {
        // 1. Straight 0 deg: center x == 0, back == distance
        ReversePathGeometry.TrackPoint p0 = ReversePathGeometry.sampleTrackPoint(2.0, 0.0, 2.9, 0.0);
        checkNear(p0.x, 0.0, 1e-6, "straight center x");
        checkNear(p0.back, 2.0, 1e-6, "straight center back");

        // 2. Right turn (+24 deg): positive x arc, concentric ordering left < center < right
        ReversePathGeometry.TrackPoint left = ReversePathGeometry.sampleTrackPoint(2.0, 24.0, 2.9, -0.92);
        ReversePathGeometry.TrackPoint center = ReversePathGeometry.sampleTrackPoint(2.0, 24.0, 2.9, 0.0);
        ReversePathGeometry.TrackPoint right = ReversePathGeometry.sampleTrackPoint(2.0, 24.0, 2.9, 0.92);
        check(center.x > 0.2, "right turn bends positive x: " + center.x);
        check(left.x < center.x && center.x < right.x, "concentric ordering preserved");

        // 3. Symmetry left (-24 deg) vs right (+24 deg)
        ReversePathGeometry.TrackPoint centerLeft = ReversePathGeometry.sampleTrackPoint(2.0, -24.0, 2.9, 0.0);
        checkNear(centerLeft.x, -center.x, 1e-6, "symmetric turn x");
        checkNear(centerLeft.back, center.back, 1e-6, "symmetric turn back");

        // 4. Tiny window worldToScreen clamping never throws and stays finite
        ReversePathGeometry.ScreenPoint sp = ReversePathGeometry.worldToScreen(
            0.0, 1.5, 100f, 130f, 65f, 4f, 50f
        );
        check(Float.isFinite(sp.x) && Float.isFinite(sp.y), "tiny window screen point finite");
    }

    private static void testEstimatorVibrationGatingAndDecay() {
        MotionSteeringEstimator est = new MotionSteeringEstimator();

        // Idle vibration (no UVC motion score -> default deadband 0.045, oscillating small yaw)
        long t = 1000L;
        for (int i = 0; i < 20; i++) {
            float vib = (i % 2 == 0) ? 0.03f : -0.03f;
            est.onGyroSample(0f, vib, 0f, 0f, 9.81f, 0f, true, t);
            t += 40L;
        }
        float idleDeg = est.step(t, false);
        checkNear(idleDeg, 0.0, 0.01, "idle vibration stays 0 deg");

        // Stationary (very low UVC motion < 1.0 -> strict deadband 0.068, confirm 130ms) rejects 0.055 rad/s tremor
        est.onVideoMotionScore(0.3f, t);
        for (int i = 0; i < 10; i++) {
            est.onGyroSample(0f, 0.055f, 0f, 0f, 9.81f, 0f, true, t);
            t += 40L;
        }
        float tremorDeg = est.step(t, false);
        checkNear(tremorDeg, 0.0, 0.01, "stationary low-motion rejects 0.055 rad/s tremor");

        // Reversing turn with strong road motion (>= 2.8) and sustained gyro yaw (-0.30 rad/s)
        est.reset();
        t = 5000L;
        est.onVideoMotionScore(4.2f, t);
        for (int i = 0; i < 10; i++) {
            est.onGyroSample(0f, -0.30f, 0f, 0f, 9.81f, 0f, true, t);
            t += 35L;
        }
        float turningDeg = est.step(t, false);
        check(turningDeg > 8.0f && turningDeg <= 32.0f, "moving reverse turn bends smoothly right: " + turningDeg);

        // Inverted steering flips sign cleanly
        est.reset();
        t = 8000L;
        est.onVideoMotionScore(4.2f, t);
        for (int i = 0; i < 10; i++) {
            est.onGyroSample(0f, -0.30f, 0f, 0f, 9.81f, 0f, true, t);
            t += 35L;
        }
        float invDeg = est.step(t, true);
        checkNear(invDeg, -turningDeg, 0.5, "inverted steering flips sign");

        // Silence > 450ms smoothly decays back toward 0 deg
        for (int i = 0; i < 20; i++) {
            t += 120L;
            invDeg = est.step(t, true);
        }
        checkNear(invDeg, 0.0, 0.4, "silence decays smoothly to 0");
    }

    private static void testUvcRoadMotionEvidence() {
        int w = 640, h = 480;
        int sz = w * h * 3 / 2;
        ByteBuffer f1 = ByteBuffer.allocateDirect(sz);
        ByteBuffer f2 = ByteBuffer.allocateDirect(sz);
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                byte v1 = (byte) ((x * 3 + y * 5) & 0xFF);
                byte v2 = (byte) (((x + 24) * 3 + (y + 12) * 5) & 0xFF);
                f1.put(y * w + x, v1);
                f2.put(y * w + x, v2);
            }
        }
        f1.position(0).limit(sz);
        f2.position(0).limit(sz);

        byte[] prev = new byte[UvcFrameSignalEvidence.ROAD_MOTION_GRID_SIZE];
        byte[] curr = new byte[UvcFrameSignalEvidence.ROAD_MOTION_GRID_SIZE];

        Float s0 = UvcFrameSignalEvidence.computeRoadMotionScore(f1, w, h, prev, curr);
        check(s0 != null && s0 >= 0f, "first sample returns non-null");
        check(f1.position() == 0 && f1.limit() == sz, "ByteBuffer position/limit preserved");
        System.arraycopy(curr, 0, prev, 0, curr.length);

        Float same = UvcFrameSignalEvidence.computeRoadMotionScore(f1, w, h, prev, curr);
        check(same != null && same < 0.01f, "identical frame has ~0 motion: " + same);

        Float moved = UvcFrameSignalEvidence.computeRoadMotionScore(f2, w, h, prev, curr);
        check(moved != null && moved > 5.0f, "shifted textured road frame produces strong motion score: " + moved);

        // Null/undersized buffer safe
        check(UvcFrameSignalEvidence.computeRoadMotionScore(null, w, h, prev, curr) == null, "null buffer returns null");
        check(UvcFrameSignalEvidence.computeRoadMotionScore(ByteBuffer.allocate(100), w, h, prev, curr) == null, "tiny buffer returns null");

        // GuideMotionHub frame size inference fallback
        GuideMotionHub.resetAll();
        GuideMotionHub.onUvcFrame(f1);
        GuideMotionHub.onUvcFrame(f2);
    }

    public static void main(String[] args) {
        testGeometryInvariants();
        testEstimatorVibrationGatingAndDecay();
        testUvcRoadMotionEvidence();
        System.out.println("ALL_GUIDE_ENGINE_UNIT_TESTS_PASSED");
    }
}

package com.tigeriq.camera;

/**
 * Concentric kinematic bicycle model referenced to the rear axle with
 * projective floor-to-screen trapezoid mapping.
 */
public final class ReversePathGeometry {
    private ReversePathGeometry() {}

    public static final class TrackPoint {
        public final double x;
        public final double back;

        public TrackPoint(double x, double back) {
            this.x = x;
            this.back = back;
        }
    }

    public static final class ScreenPoint {
        public final float x;
        public final float y;

        public ScreenPoint(float x, float y) {
            this.x = x;
            this.y = y;
        }
    }

    private static double clamp(double v, double lo, double hi) {
        return Math.max(lo, Math.min(hi, v));
    }

    private static float clampF(float v, float lo, float hi) {
        return Math.max(lo, Math.min(hi, v));
    }

    /** Computes concentric offset point along rear-axle bicycle arc for any tire or rail offset. */
    public static TrackPoint sampleTrackPoint(
            double distanceBack,
            double roadWheelDegrees,
            double wheelbaseMeters,
            double lateralOffsetMeters) {
        double safeBack = clamp(distanceBack, 0.0, 6.0);
        double safeAngle = clamp(roadWheelDegrees, -35.0, 35.0);
        double safeWheelbase = clamp(wheelbaseMeters, 1.5, 5.0);
        double safeOffset = clamp(lateralOffsetMeters, -1.5, 1.5);
        double k = Math.tan(safeAngle * Math.PI / 180.0) / safeWheelbase;
        double heading = k * safeBack;
        double x = Math.abs(k) < 1e-9 ? 0.0 : (1.0 - Math.cos(heading)) / k;
        double backwards = Math.abs(k) < 1e-9 ? safeBack : Math.sin(heading) / k;
        return new TrackPoint(
            x + safeOffset * Math.cos(heading),
            backwards - safeOffset * Math.sin(heading)
        );
    }

    /** Projects floor world meters (x right, back away from bumper) onto Canvas coordinates. */
    public static ScreenPoint worldToScreen(
            double worldX,
            double worldBack,
            float cx,
            float bottomY,
            float topY,
            float bottomHalfW,
            float topHalfW) {
        return worldToScreen(worldX, worldBack, cx, bottomY, topY, bottomHalfW, topHalfW, 3.0, 0.90);
    }

    public static ScreenPoint worldToScreen(
            double worldX,
            double worldBack,
            float cx,
            float bottomY,
            float topY,
            float bottomHalfW,
            float topHalfW,
            double referenceDistanceBack,
            double referenceHalfWidthMeters) {
        float safeBottomHalfW = Math.max(20f, bottomHalfW);
        float maxTopHalfW = safeBottomHalfW * 0.92f;
        float minTopHalfW = Math.min(10f, maxTopHalfW);
        float safeTopHalfW = clampF(topHalfW, minTopHalfW, maxTopHalfW);
        double ratio = safeBottomHalfW / (double) safeTopHalfW;
        double z0 = Math.max(0.5, referenceDistanceBack) / Math.max(0.05, ratio - 1.0);
        double zCam = Math.max(0.05, worldBack) + z0;
        float tPersp = (float) (z0 / zCam);
        float perspSpan = Math.max(0.05f, 1.0f - (safeTopHalfW / safeBottomHalfW));
        float uY = (1.0f - tPersp) / perspSpan;
        float screenY = bottomY - uY * (bottomY - topY);
        float pxPerMeter = (safeBottomHalfW * tPersp) / (float) Math.max(0.2, referenceHalfWidthMeters);
        return new ScreenPoint(cx + (float) worldX * pxPerMeter, screenY);
    }
}

package com.tigeriq.camera;

import java.nio.ByteBuffer;

/**
 * Non-destructive NV21 lower-road optical luma motion scorer immune to uniform AGC exposure jumps.
 */
public final class UvcFrameSignalEvidence {
    public static final int ROAD_MOTION_GRID_SIZE = 32; // 8 cols x 4 rows across lower road band

    private UvcFrameSignalEvidence() {}

    public static Float computeRoadMotionScore(
            ByteBuffer frame,
            int width,
            int height,
            byte[] previousSample,
            byte[] outSample) {
        if (frame == null || previousSample == null || outSample == null) return null;
        if (width < 16 || height < 16) return null;
        if (previousSample.length < ROAD_MOTION_GRID_SIZE || outSample.length < ROAD_MOTION_GRID_SIZE) {
            return null;
        }
        long pixelCountLong = (long) width * (long) height;
        if (pixelCountLong <= 0L || pixelCountLong > Integer.MAX_VALUE || frame.remaining() < pixelCountLong) {
            return null;
        }

        ByteBuffer read = frame.asReadOnlyBuffer();
        int base = read.position();
        int idx = 0;
        int sumCur = 0;
        int sumPrev = 0;

        for (int row = 0; row < 4; row++) {
            int y = (int) ((0.56f + row * 0.10f) * height);
            if (y < 0) y = 0;
            if (y >= height) y = height - 1;
            int rowBase = base + y * width;
            for (int col = 0; col < 8; col++) {
                int x = (int) ((0.15f + col * 0.10f) * width);
                if (x < 0) x = 0;
                if (x >= width) x = width - 1;
                int lumaCur = read.get(rowBase + x) & 0xFF;
                int lumaPrev = previousSample[idx] & 0xFF;
                outSample[idx] = (byte) lumaCur;
                sumCur += lumaCur;
                sumPrev += lumaPrev;
                idx++;
            }
        }

        float meanCur = sumCur / (float) ROAD_MOTION_GRID_SIZE;
        float meanPrev = sumPrev / (float) ROAD_MOTION_GRID_SIZE;
        float mad = 0f;
        for (int i = 0; i < ROAD_MOTION_GRID_SIZE; i++) {
            float cur = (outSample[i] & 0xFF) - meanCur;
            float prev = (previousSample[i] & 0xFF) - meanPrev;
            mad += Math.abs(cur - prev);
        }
        return mad / (float) ROAD_MOTION_GRID_SIZE;
    }
}

package com.tigeriq.camera;

/**
 * Gravity-aligned gyroscope yaw estimator with UVC road-texture motion gating
 * and calm MEMS bias tracking to prevent idle stationary vibration curvature.
 */
public final class MotionSteeringEstimator {
    private float biasRadPerSec = 0f;
    private float yawSlowRadPerSec = 0f;
    private long lastGyroMs = 0L;
    private long lastStepMs = 0L;
    private long turnHoldStartMs = 0L;
    private int turnHoldSign = 0;
    private float baseDegrees = 0f;

    private volatile float lastMotionScore = 0f;
    private volatile long lastMotionMs = 0L;

    private static float clamp(float v, float lo, float hi) {
        return Math.max(lo, Math.min(hi, v));
    }

    private static long clampL(long v, long lo, long hi) {
        return Math.max(lo, Math.min(hi, v));
    }

    public synchronized void reset() {
        yawSlowRadPerSec = 0f;
        lastGyroMs = 0L;
        lastStepMs = 0L;
        turnHoldStartMs = 0L;
        turnHoldSign = 0;
        baseDegrees = 0f;
    }

    public void onVideoMotionScore(float score, long timestampMs) {
        if (!Float.isFinite(score) || score < 0f) return;
        lastMotionScore = score;
        lastMotionMs = timestampMs;
    }

    public synchronized void onGyroSample(
            float wx, float wy, float wz,
            float gx, float gy, float gz,
            boolean hasGravity,
            long timestampMs) {
        float gNormSq = gx * gx + gy * gy + gz * gz;
        float rawYaw = (hasGravity && gNormSq > 25f)
            ? (wx * gx + wy * gy + wz * gz) / (float) Math.sqrt(gNormSq)
            : wy;
        if (!Float.isFinite(rawYaw)) return;
        float clampedYaw = clamp(rawYaw, -4.0f, 4.0f);

        float dtSec;
        if (lastGyroMs == 0L || timestampMs <= lastGyroMs) {
            dtSec = 0.03f;
        } else {
            long delta = timestampMs - lastGyroMs;
            if (delta > 1000L) {
                yawSlowRadPerSec = 0f;
                turnHoldStartMs = 0L;
                turnHoldSign = 0;
                dtSec = 0.03f;
            } else {
                dtSec = clampL(delta, 1L, 250L) / 1000f;
            }
        }
        lastGyroMs = timestampMs;

        if (Math.abs(clampedYaw - biasRadPerSec) < 0.028f && Math.abs(yawSlowRadPerSec) < 0.035f) {
            float biasAlpha = clamp(dtSec / 1.2f, 0.005f, 0.05f);
            biasRadPerSec += biasAlpha * (clampedYaw - biasRadPerSec);
        }

        float cleanYaw = clampedYaw - biasRadPerSec;
        float lpfAlpha = clamp(dtSec / (0.14f + dtSec), 0.05f, 0.70f);
        yawSlowRadPerSec += lpfAlpha * (cleanYaw - yawSlowRadPerSec);

        float activeDeadband = resolveDeadband(timestampMs);
        float absYaw = Math.abs(yawSlowRadPerSec);
        if (absYaw > activeDeadband) {
            int sign = yawSlowRadPerSec > 0f ? 1 : -1;
            if (sign != turnHoldSign) {
                turnHoldSign = sign;
                turnHoldStartMs = timestampMs;
            }
        } else {
            turnHoldSign = 0;
            turnHoldStartMs = 0L;
        }
    }

    public synchronized float step(long nowMs, boolean inverted) {
        float dtSec = (lastStepMs == 0L || nowMs <= lastStepMs)
            ? 0.033f
            : clampL(nowMs - lastStepMs, 1L, 250L) / 1000f;
        lastStepMs = nowMs;

        if (lastGyroMs > 0L && nowMs - lastGyroMs > 450L) {
            float decayAlpha = clamp(dtSec / (0.18f + dtSec), 0.05f, 0.70f);
            yawSlowRadPerSec *= (1f - decayAlpha);
            if (Math.abs(yawSlowRadPerSec) < 0.01f) yawSlowRadPerSec = 0f;
            turnHoldSign = 0;
            turnHoldStartMs = 0L;
        }

        float activeDeadband = resolveDeadband(nowMs);
        long confirmMs = resolveConfirmMs(nowMs);
        float absYaw = Math.abs(yawSlowRadPerSec);
        float targetBase;
        if (turnHoldSign != 0 && turnHoldStartMs > 0L
                && absYaw > activeDeadband
                && nowMs - turnHoldStartMs >= confirmMs) {
            float dir = (yawSlowRadPerSec < 0f) ? 1f : -1f;
            float strength = clamp((absYaw - activeDeadband) * 145f, 0f, 32f);
            targetBase = dir * strength;
        } else {
            targetBase = 0f;
        }

        float tau;
        if (targetBase == 0f) {
            tau = 0.12f;
        } else if (Math.abs(targetBase) > Math.abs(baseDegrees)) {
            tau = 0.10f;
        } else {
            tau = 0.18f;
        }
        float smoothAlpha = clamp(dtSec / (tau + dtSec), 0.08f, 0.75f);
        baseDegrees += smoothAlpha * (targetBase - baseDegrees);
        if (Math.abs(baseDegrees) < 0.35f && targetBase == 0f) {
            baseDegrees = 0f;
        }
        return inverted ? -baseDegrees : baseDegrees;
    }

    private float resolveDeadband(long nowMs) {
        long age = nowMs - lastMotionMs;
        if (lastMotionMs <= 0L || age < 0L || age > 600L) return 0.045f;
        if (lastMotionScore >= 2.8f) return 0.042f;
        if (lastMotionScore < 1.0f) return 0.068f;
        return 0.050f;
    }

    private long resolveConfirmMs(long nowMs) {
        long age = nowMs - lastMotionMs;
        if (lastMotionMs <= 0L || age < 0L || age > 600L) return 80L;
        if (lastMotionScore >= 2.8f) return 30L;
        if (lastMotionScore < 1.0f) return 130L;
        return 75L;
    }
}

package com.tigeriq.camera;

import java.nio.ByteBuffer;

/**
 * Thread-safe bridge forwarding NV21 IFrameCallback road motion and IMU gyroscope
 * samples into the shared MotionSteeringEstimator.
 */
public final class GuideMotionHub {
    private static final MotionSteeringEstimator ESTIMATOR = new MotionSteeringEstimator();
    private static final byte[] PREV_SAMPLE = new byte[UvcFrameSignalEvidence.ROAD_MOTION_GRID_SIZE];
    private static final byte[] CURR_SAMPLE = new byte[UvcFrameSignalEvidence.ROAD_MOTION_GRID_SIZE];
    private static final Object FRAME_LOCK = new Object();

    private static volatile int sFrameWidth = 0;
    private static volatile int sFrameHeight = 0;
    private static volatile long sLastMotionAtMs = 0L;
    private static boolean sHasPrevSample = false;

    private GuideMotionHub() {}

    public static long monoMs() {
        return System.nanoTime() / 1_000_000L;
    }

    public static void setFrameSize(int width, int height) {
        if (width > 0 && height > 0) {
            if (sFrameWidth != width || sFrameHeight != height) {
                resetVideoMotion();
                sFrameWidth = width;
                sFrameHeight = height;
            }
        }
    }

    public static void resetVideoMotion() {
        synchronized (FRAME_LOCK) {
            sHasPrevSample = false;
            sLastMotionAtMs = 0L;
        }
    }

    public static void resetAll() {
        resetVideoMotion();
        ESTIMATOR.reset();
    }

    public static void onGyroSample(
            float wx, float wy, float wz,
            float gx, float gy, float gz,
            boolean hasGravity) {
        ESTIMATOR.onGyroSample(wx, wy, wz, gx, gy, gz, hasGravity, monoMs());
    }

    public static float stepDegrees(boolean inverted) {
        return ESTIMATOR.step(monoMs(), inverted);
    }

    public static void onUvcFrame(ByteBuffer frame) {
        if (frame == null) return;
        try {
            long now = monoMs();
            synchronized (FRAME_LOCK) {
                if (sLastMotionAtMs > 0L && (now - sLastMotionAtMs) >= 0L && (now - sLastMotionAtMs) < 100L) {
                    return;
                }
                int w = sFrameWidth;
                int h = sFrameHeight;
                int rem = frame.remaining();
                if (w <= 0 || h <= 0 || (long) w * (long) h > rem) {
                    int[] dims = inferNv21Size(rem);
                    if (dims == null) return;
                    w = dims[0];
                    h = dims[1];
                }
                sLastMotionAtMs = now;
                Float score = UvcFrameSignalEvidence.computeRoadMotionScore(frame, w, h, PREV_SAMPLE, CURR_SAMPLE);
                if (score != null) {
                    System.arraycopy(CURR_SAMPLE, 0, PREV_SAMPLE, 0, PREV_SAMPLE.length);
                    if (sHasPrevSample) {
                        ESTIMATOR.onVideoMotionScore(score, now);
                    } else {
                        sHasPrevSample = true;
                    }
                }
            }
        } catch (Throwable ignored) {
        }
    }

    private static int[] inferNv21Size(int remaining) {
        int[][] common = {
            {1920, 1080}, {1280, 720}, {1024, 768}, {800, 600},
            {720, 576}, {720, 480}, {640, 480}, {320, 240}
        };
        for (int[] c : common) {
            int nv21Bytes = (c[0] * c[1] * 3) / 2;
            if (remaining >= nv21Bytes && remaining <= nv21Bytes + 4096) {
                return c;
            }
        }
        return null;
    }
}

