3: /**
4:  * Gravity-aligned gyroscope yaw estimator with UVC road-texture motion gating
5:  * and calm MEMS bias tracking to prevent idle stationary vibration curvature.
6:  */
7: public final class MotionSteeringEstimator {
8:     private float biasRadPerSec = 0f;
9:     private float yawSlowRadPerSec = 0f;
10:     private long lastGyroMs = 0L;
11:     private long lastStepMs = 0L;
12:     private long turnHoldStartMs = 0L;
13:     private int turnHoldSign = 0;
14:     private float baseDegrees = 0f;
15: 
16:     private volatile float lastMotionScore = 0f;
17:     private volatile long lastMotionMs = 0L;
18: 
19:     private static float clamp(float v, float lo, float hi) {
20:         return Math.max(lo, Math.min(hi, v));
21:     }
22: 
23:     private static long clampL(long v, long lo, long hi) {
24:         return Math.max(lo, Math.min(hi, v));
25:     }
26: 
27:     public synchronized void reset() {
28:         yawSlowRadPerSec = 0f;
29:         lastGyroMs = 0L;
30:         lastStepMs = 0L;
31:         turnHoldStartMs = 0L;
32:         turnHoldSign = 0;
33:         baseDegrees = 0f;
34:     }
35: 
36:     public void onVideoMotionScore(float score, long timestampMs) {
37:         if (!Float.isFinite(score) || score < 0f) return;
38:         lastMotionScore = score;
39:         lastMotionMs = timestampMs;
40:     }
41: 
42:     public synchronized void onGyroSample(
43:             float wx, float wy, float wz,
44:             float gx, float gy, float gz,
45:             boolean hasGravity,
46:             long timestampMs) {
47:         float gNormSq = gx * gx + gy * gy + gz * gz;
48:         float rawYaw = (hasGravity && gNormSq > 25f)
49:             ? (wx * gx + wy * gy + wz * gz) / (float) Math.sqrt(gNormSq)
50:             : wy;
51:         if (!Float.isFinite(rawYaw)) return;
52:         float clampedYaw = clamp(rawYaw, -4.0f, 4.0f);
53: 
54:         float dtSec;
55:         if (lastGyroMs == 0L || timestampMs <= lastGyroMs) {
56:             dtSec = 0.03f;
57:         } else {
58:             long delta = timestampMs - lastGyroMs;
59:             if (delta > 1000L) {
60:                 yawSlowRadPerSec = 0f;
61:                 turnHoldStartMs = 0L;
62:                 turnHoldSign = 0;
63:                 dtSec = 0.03f;
64:             } else {
65:                 dtSec = clampL(delta, 1L, 250L) / 1000f;
66:             }
67:         }
68:         lastGyroMs = timestampMs;
69: 
70:         if (Math.abs(clampedYaw - biasRadPerSec) < 0.028f && Math.abs(yawSlowRadPerSec) < 0.035f) {
71:             float biasAlpha = clamp(dtSec / 1.2f, 0.005f, 0.05f);
72:             biasRadPerSec += biasAlpha * (clampedYaw - biasRadPerSec);
73:         }
74: 
75:         float cleanYaw = clampedYaw - biasRadPerSec;
76:         float lpfAlpha = clamp(dtSec / (0.14f + dtSec), 0.05f, 0.70f);
77:         yawSlowRadPerSec += lpfAlpha * (cleanYaw - yawSlowRadPerSec);
78: 
79:         float activeDeadband = resolveDeadband(timestampMs);
80:         float absYaw = Math.abs(yawSlowRadPerSec);
81:         if (absYaw > activeDeadband) {
82:             int sign = yawSlowRadPerSec > 0f ? 1 : -1;
83:             if (sign != turnHoldSign) {
84:                 turnHoldSign = sign;
85:                 turnHoldStartMs = timestampMs;
86:             }
87:         } else {
88:             turnHoldSign = 0;
89:             turnHoldStartMs = 0L;
90:         }
91:     }
92: 
93:     public synchronized float step(long nowMs, boolean inverted) {
94:         float dtSec = (lastStepMs == 0L || nowMs <= lastStepMs)
95:             ? 0.033f
96:             : clampL(nowMs - lastStepMs, 1L, 250L) / 1000f;
97:         lastStepMs = nowMs;
98: 
99:         if (lastGyroMs > 0L && nowMs - lastGyroMs > 450L) {
100:             float decayAlpha = clamp(dtSec / (0.18f + dtSec), 0.05f, 0.70f);
101:             yawSlowRadPerSec *= (1f - decayAlpha);
102:             if (Math.abs(yawSlowRadPerSec) < 0.01f) yawSlowRadPerSec = 0f;
103:             turnHoldSign = 0;
104:             turnHoldStartMs = 0L;
105:         }
106: 
107:         float activeDeadband = resolveDeadband(nowMs);
108:         long confirmMs = resolveConfirmMs(nowMs);
109:         float absYaw = Math.abs(yawSlowRadPerSec);
110:         float targetBase;
111:         if (turnHoldSign != 0 && turnHoldStartMs > 0L
112:                 && absYaw > activeDeadband
113:                 && nowMs - turnHoldStartMs >= confirmMs) {
114:             float dir = (yawSlowRadPerSec < 0f) ? 1f : -1f;
115:             float strength = clamp((absYaw - activeDeadband) * 145f, 0f, 32f);
116:             targetBase = dir * strength;
117:         } else {
118:             targetBase = 0f;
119:         }
