    static void drawBadge(Graphics2D g, int w, int h, float ax, float ay, Color col, String lbl, float uiScale) {
        float ts = Math.max(9.5f, Math.min(24f, 11.5f * uiScale));
        g.setFont(new Font("SansSerif", Font.BOLD, Math.round(ts)));
        FontMetrics fm = g.getFontMetrics();
        float pw = fm.stringWidth(lbl) + 11f * uiScale;
        float ph = ts + 6f * uiScale;
        float pad = 5f * uiScale;
        float by = Math.max(ph*0.5f+pad, Math.min(h-ph*0.5f-pad, ay));
        float bx = Math.min(ax + 5f*uiScale + pw*0.5f, w - pad - pw*0.5f);
        g.setColor(new Color(12,16,22,222));
        g.fill(new RoundRectangle2D.Float(bx-pw*0.5f, by-ph*0.5f, pw, ph, 4.5f*uiScale, 4.5f*uiScale));
        g.setColor(col); g.setStroke(new BasicStroke(1.4f*uiScale));
        g.draw(new RoundRectangle2D.Float(bx-pw*0.5f, by-ph*0.5f, pw, ph, 4.5f*uiScale, 4.5f*uiScale));
        g.drawString(lbl, bx - fm.stringWidth(lbl)*0.5f, by + (fm.getAscent()-fm.getDescent())*0.5f);
    }
