import com.tigeriq.camera.RemoteKeyShortcutEngine;
import com.tigeriq.camera.RemoteKeyShortcutEngine.Action;
import java.util.concurrent.atomic.AtomicInteger;

public class RemoteKeyShortcutUnitTest {
    private static void check(boolean cond, String msg) {
        if (!cond) {
            throw new AssertionError("FAIL: " + msg);
        }
    }

    private static void testShortPressReplaysAudioAndNeverTogglesCamera() {
        RemoteKeyShortcutEngine engine = new RemoteKeyShortcutEngine();
        engine.configure(true, RemoteKeyShortcutEngine.KEYCODE_VOLUME_UP, 800L);

        long t = 10_000L;
        // User taps VOL+ for 180ms (< 800ms hold threshold) -> press is held pending, then released triggers audio passthrough
        Action d = engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_DOWN, RemoteKeyShortcutEngine.KEYCODE_VOLUME_UP, 0, t);
        check(d == Action.CONSUME_PENDING_HOLD, "short press down must consume pending hold");
        check(engine.isHoldPending(), "hold should be pending after ACTION_DOWN");

        // Timeout check before 800ms must NOT fire
        check(engine.onHoldTimeout(t + 180L) == Action.CONSUME_ONLY, "no timeout before threshold");

        Action u = engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_UP, RemoteKeyShortcutEngine.KEYCODE_VOLUME_UP, 0, t + 180L);
        check(u == Action.REPLAY_SHORT_PRESS, "release before holdMs must replay short press audio");
        check(!engine.isHoldPending(), "hold cleared after release");
    }

    private static void testHoldUnder2sTriggersCameraExactlyOnce() {
        RemoteKeyShortcutEngine engine = new RemoteKeyShortcutEngine();
        engine.configure(true, RemoteKeyShortcutEngine.KEYCODE_MEDIA_NEXT, 800L);

        long t = 20_000L;
        Action d = engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_DOWN, RemoteKeyShortcutEngine.KEYCODE_MEDIA_NEXT, 0, t);
        check(d == Action.CONSUME_PENDING_HOLD, "down enters hold pending");

        // OS repeats ACTION_DOWN (repeatCount > 0) at 450ms -> still wait without re-starting timer
        Action r1 = engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_DOWN, RemoteKeyShortcutEngine.KEYCODE_MEDIA_NEXT, 1, t + 450L);
        check(r1 == Action.CONSUME_ONLY, "repeat before threshold stays consumed");

        // Timer fires cleanly at 800ms (< 2000ms) -> CAMERA TOGGLE ONCE!
        Action timeout = engine.onHoldTimeout(t + 800L);
        check(timeout == Action.TRIGGER_CAMERA, "timeout at 800ms (< 2s) must trigger camera");
        check(!engine.isHoldPending(), "pending cleared once triggered");

        // Duplicate timeout call never double-triggers
        check(engine.onHoldTimeout(t + 1200L) == Action.CONSUME_ONLY, "duplicate timeout must not retrigger");

        // Subsequent repeat at 1300ms and final ACTION_UP at 1400ms must NOT retrigger camera or replay audio
        Action r2 = engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_DOWN, RemoteKeyShortcutEngine.KEYCODE_MEDIA_NEXT, 5, t + 1300L);
        check(r2 == Action.CONSUME_ONLY, "post-trigger repeat consumed silently");
        Action u = engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_UP, RemoteKeyShortcutEngine.KEYCODE_MEDIA_NEXT, 0, t + 1400L);
        check(u == Action.CONSUME_ONLY, "post-trigger release must not replay short press");
    }

    private static void testReleaseFallbackBetweenHoldThresholdAnd2sTriggersOnce() {
        RemoteKeyShortcutEngine engine = new RemoteKeyShortcutEngine();
        engine.configure(true, RemoteKeyShortcutEngine.KEYCODE_VOICE_ASSIST, 700L);

        long t = 30_000L;
        Action d = engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_DOWN, RemoteKeyShortcutEngine.KEYCODE_VOICE_ASSIST, 0, t);
        check(d == Action.CONSUME_PENDING_HOLD, "voice down pending hold");

        // Suppose timer runnable didn't beat release at 950ms (< 2000ms) -> UP still triggers camera cleanly once
        Action u = engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_UP, RemoteKeyShortcutEngine.KEYCODE_VOICE_ASSIST, 0, t + 950L);
        check(u == Action.TRIGGER_CAMERA, "release in [holdMs, 2000ms) triggers camera if timer hasn't run");
    }

    private static void testThresholdClampedStrictlyBelow2SecondsAndZeroModeWorks() {
        RemoteKeyShortcutEngine engine = new RemoteKeyShortcutEngine();
        engine.configure(true, RemoteKeyShortcutEngine.KEYCODE_MEDIA_PLAY_PAUSE, 3500L);
        check(engine.getHoldThresholdMs() < 2000L, "hold threshold must always clamp < 2000ms: " + engine.getHoldThresholdMs());
        check(engine.getHoldThresholdMs() == RemoteKeyShortcutEngine.MAX_HOLD_MS, "clamped to MAX_HOLD_MS");

        // Instant mode (0ms) for a dedicated Voice/Camera button triggers on DOWN and consumes UP
        engine.configure(true, RemoteKeyShortcutEngine.KEYCODE_VOICE_ASSIST, 0L);
        Action d = engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_DOWN, RemoteKeyShortcutEngine.KEYCODE_VOICE_ASSIST, 0, 40_000L);
        check(d == Action.TRIGGER_CAMERA, "0ms instant mode triggers camera on ACTION_DOWN");
        Action u = engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_UP, RemoteKeyShortcutEngine.KEYCODE_VOICE_ASSIST, 0, 40_120L);
        check(u == Action.CONSUME_ONLY, "0ms UP consumed without double-trigger or voice dialog");
    }

    private static void testOtherKeysAndDisabledStatePassThrough() {
        RemoteKeyShortcutEngine engine = new RemoteKeyShortcutEngine();
        engine.configure(true, RemoteKeyShortcutEngine.KEYCODE_VOICE_ASSIST, 800L);

        // Other 4 buttons on BT remote must pass straight through untouched
        check(engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_DOWN, RemoteKeyShortcutEngine.KEYCODE_VOLUME_UP, 0, 50_000L) == Action.PASS_THROUGH,
            "non-target VOL+ down passes through");
        check(engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_UP, RemoteKeyShortcutEngine.KEYCODE_VOLUME_UP, 0, 50_100L) == Action.PASS_THROUGH,
            "non-target VOL+ up passes through");

        // Disabled engine passes even target key through
        engine.configure(false, RemoteKeyShortcutEngine.KEYCODE_VOICE_ASSIST, 800L);
        check(engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_DOWN, RemoteKeyShortcutEngine.KEYCODE_VOICE_ASSIST, 0, 51_000L) == Action.PASS_THROUGH,
            "disabled shortcut passes through");
    }

    private static void testSyntheticReplayBypassPreventsFeedbackLoop() {
        RemoteKeyShortcutEngine engine = new RemoteKeyShortcutEngine();
        engine.configure(true, RemoteKeyShortcutEngine.KEYCODE_MEDIA_PLAY_PAUSE, 800L);

        long t = 60_000L;
        engine.markSyntheticPassthrough(RemoteKeyShortcutEngine.KEYCODE_MEDIA_PLAY_PAUSE, t);
        check(engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_DOWN, RemoteKeyShortcutEngine.KEYCODE_MEDIA_PLAY_PAUSE, 0, t + 10L) == Action.PASS_THROUGH,
            "synthetic replayed DOWN must pass through");
        check(engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_UP, RemoteKeyShortcutEngine.KEYCODE_MEDIA_PLAY_PAUSE, 0, t + 20L) == Action.PASS_THROUGH,
            "synthetic replayed UP must pass through");

        // Subsequent real user press triggers normal interception again
        check(engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_DOWN, RemoteKeyShortcutEngine.KEYCODE_MEDIA_PLAY_PAUSE, 0, t + 500L) == Action.CONSUME_PENDING_HOLD,
            "subsequent real press intercepts normally");
    }

    private static void testLearnModeCapturesSafeKeyAndIgnoresSystemNavKeys() {
        RemoteKeyShortcutEngine engine = new RemoteKeyShortcutEngine();
        engine.configure(false, RemoteKeyShortcutEngine.KEYCODE_VOICE_ASSIST, 800L);
        AtomicInteger learned = new AtomicInteger(-1);
        engine.startLearnMode(learned::set);

        // Unsafe Home/Back/Power keys must NOT be captured
        Action home = engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_DOWN, RemoteKeyShortcutEngine.KEYCODE_HOME, 0, 70_000L);
        check(home == Action.PASS_THROUGH && learned.get() == -1, "HOME must not be captured in learn mode");

        // Steering-wheel Next button IS captured even if shortcut was disabled before
        Action capDown = engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_DOWN, RemoteKeyShortcutEngine.KEYCODE_MEDIA_NEXT, 0, 70_100L);
        check(capDown == Action.LEARN_CAPTURED, "learn mode captures MEDIA_NEXT down");
        check(learned.get() == RemoteKeyShortcutEngine.KEYCODE_MEDIA_NEXT, "callback received MEDIA_NEXT");

        // Corresponding UP is consumed cleanly without triggering camera or short press
        Action capUp = engine.onKeyEvent(RemoteKeyShortcutEngine.ACTION_UP, RemoteKeyShortcutEngine.KEYCODE_MEDIA_NEXT, 0, 70_220L);
        check(capUp == Action.CONSUME_ONLY, "learn UP consumed cleanly");
        check(!engine.isLearnModeActive(), "learn mode exits after single capture");
    }

    private static void testFormatKeyNamesReadable() {
        check(RemoteKeyShortcutEngine.formatKeyName(RemoteKeyShortcutEngine.KEYCODE_VOLUME_UP).contains("VOL+"), "VOL+ label");
        check(RemoteKeyShortcutEngine.formatKeyName(RemoteKeyShortcutEngine.KEYCODE_MEDIA_PLAY_PAUSE).contains("Play"), "Play/Pause label");
        check(RemoteKeyShortcutEngine.formatKeyName(RemoteKeyShortcutEngine.KEYCODE_VOICE_ASSIST).contains("Voice"), "Voice label");
    }

    public static void main(String[] args) {
        testShortPressReplaysAudioAndNeverTogglesCamera();
        testHoldUnder2sTriggersCameraExactlyOnce();
        testReleaseFallbackBetweenHoldThresholdAnd2sTriggersOnce();
        testThresholdClampedStrictlyBelow2SecondsAndZeroModeWorks();
        testOtherKeysAndDisabledStatePassThrough();
        testSyntheticReplayBypassPreventsFeedbackLoop();
        testLearnModeCapturesSafeKeyAndIgnoresSystemNavKeys();
        testFormatKeyNamesReadable();
        System.out.println("ALL_REMOTE_KEY_SHORTCUT_TESTS_PASSED");
    }
}

package com.tigeriq.camera;

/**
 * Pure-Java deterministic state machine for Bluetooth steering-wheel remote shortcuts.
 * Differentiates quick audio presses (< holdThresholdMs) from intentional long holds
 * (>= holdThresholdMs, strictly < 2000ms) that toggle UltraCar Camera Popup without
 * interfering with unrelated remote keys.
 */
public final class RemoteKeyShortcutEngine {
    public static final int ACTION_DOWN = 0;
    public static final int ACTION_UP = 1;
    public static final int ACTION_MULTIPLE = 2;

    public static final int KEYCODE_UNKNOWN = 0;
    public static final int KEYCODE_HOME = 3;
    public static final int KEYCODE_BACK = 4;
    public static final int KEYCODE_DPAD_CENTER = 23;
    public static final int KEYCODE_VOLUME_UP = 24;
    public static final int KEYCODE_VOLUME_DOWN = 25;
    public static final int KEYCODE_POWER = 26;
    public static final int KEYCODE_CAMERA = 27;
    public static final int KEYCODE_ENTER = 66;
    public static final int KEYCODE_HEADSETHOOK = 79;
    public static final int KEYCODE_MEDIA_PLAY_PAUSE = 85;
    public static final int KEYCODE_MEDIA_STOP = 86;
    public static final int KEYCODE_MEDIA_NEXT = 87;
    public static final int KEYCODE_MEDIA_PREVIOUS = 88;
    public static final int KEYCODE_MEDIA_REWIND = 89;
    public static final int KEYCODE_MEDIA_FAST_FORWARD = 90;
    public static final int KEYCODE_MEDIA_PLAY = 126;
    public static final int KEYCODE_MEDIA_PAUSE = 127;
    public static final int KEYCODE_APP_SWITCH = 187;
    public static final int KEYCODE_ASSIST = 219;
    public static final int KEYCODE_VOICE_ASSIST = 231;

    public static final long DEFAULT_HOLD_MS = 800L;
    public static final long MIN_HOLD_MS = 0L;
    public static final long MAX_HOLD_MS = 1900L;
    public static final long HARD_UPPER_BOUND_MS = 2000L;
    private static final long SYNTHETIC_BYPASS_WINDOW_MS = 600L;

    public enum Action {
        PASS_THROUGH,
        CONSUME_PENDING_HOLD,
        CONSUME_ONLY,
        TRIGGER_CAMERA,
        REPLAY_SHORT_PRESS,
        LEARN_CAPTURED
    }

    public interface LearnCallback {
        void onKeyCaptured(int keyCode);
    }

    private boolean enabled = false;
    private int targetKeyCode = KEYCODE_VOICE_ASSIST;
    private long holdThresholdMs = DEFAULT_HOLD_MS;

    private boolean downActive = false;
    private long downTimeMs = 0L;
    private boolean holdTriggered = false;
    private long activePressId = 0L;

    private boolean learnMode = false;
    private LearnCallback learnCallback = null;
    private int capturingUpForKeyCode = KEYCODE_UNKNOWN;

    private int syntheticKeyCode = KEYCODE_UNKNOWN;
    private long syntheticExpiryMs = 0L;
    private int syntheticRemainingEvents = 0;

    public synchronized void configure(boolean enabled, int targetKeyCode, long holdThresholdMs) {
        this.enabled = enabled;
        this.targetKeyCode = targetKeyCode;
        this.holdThresholdMs = clampHoldMs(holdThresholdMs);
        clearPendingPress();
    }

    public synchronized void reset() {
        clearPendingPress();
        learnMode = false;
        learnCallback = null;
        capturingUpForKeyCode = KEYCODE_UNKNOWN;
        syntheticKeyCode = KEYCODE_UNKNOWN;
        syntheticExpiryMs = 0L;
        syntheticRemainingEvents = 0;
    }

    public static long clampHoldMs(long ms) {
        if (ms < MIN_HOLD_MS) return MIN_HOLD_MS;
        if (ms > MAX_HOLD_MS) return MAX_HOLD_MS;
        return ms;
    }

    public synchronized boolean isEnabled() {
        return enabled;
    }

    public synchronized int getTargetKeyCode() {
        return targetKeyCode;
    }

    public synchronized long getHoldThresholdMs() {
        return holdThresholdMs;
    }

    public synchronized boolean isHoldPending() {
        return downActive && !holdTriggered;
    }

    public synchronized long getActivePressId() {
        return activePressId;
    }

    public synchronized void startLearnMode(LearnCallback callback) {
        clearPendingPress();
        this.learnMode = true;
        this.learnCallback = callback;
        this.capturingUpForKeyCode = KEYCODE_UNKNOWN;
    }

    public synchronized void stopLearnMode() {
        this.learnMode = false;
        this.learnCallback = null;
        this.capturingUpForKeyCode = KEYCODE_UNKNOWN;
    }

    public synchronized boolean isLearnModeActive() {
        return learnMode;
    }

    public synchronized void markSyntheticPassthrough(int keyCode, long nowMs) {
        this.syntheticKeyCode = keyCode;
        this.syntheticExpiryMs = nowMs + SYNTHETIC_BYPASS_WINDOW_MS;
        this.syntheticRemainingEvents = 2; // DOWN + UP
    }

    public static boolean isSafeMappableKey(int keyCode) {
        if (keyCode <= KEYCODE_UNKNOWN) return false;
        return keyCode != KEYCODE_HOME
                && keyCode != KEYCODE_BACK
                && keyCode != KEYCODE_POWER
                && keyCode != KEYCODE_APP_SWITCH;
    }

    public synchronized Action onKeyEvent(int action, int keyCode, int repeatCount, long nowMs) {
        if (syntheticRemainingEvents > 0 && keyCode == syntheticKeyCode && nowMs <= syntheticExpiryMs) {
            syntheticRemainingEvents--;
            if (syntheticRemainingEvents <= 0) {
                syntheticKeyCode = KEYCODE_UNKNOWN;
                syntheticExpiryMs = 0L;
            }
            return Action.PASS_THROUGH;
        }

        if (keyCode == capturingUpForKeyCode && action == ACTION_UP) {
            capturingUpForKeyCode = KEYCODE_UNKNOWN;
            return Action.CONSUME_ONLY;
        }

        if (learnMode) {
            if (!isSafeMappableKey(keyCode)) {
                return Action.PASS_THROUGH;
            }
            if (action == ACTION_DOWN && repeatCount == 0) {
                LearnCallback cb = this.learnCallback;
                this.learnMode = false;
                this.learnCallback = null;
                this.capturingUpForKeyCode = keyCode;
                clearPendingPress();
                if (cb != null) {
                    cb.onKeyCaptured(keyCode);
                }
                return Action.LEARN_CAPTURED;
            }
            return Action.CONSUME_ONLY;
        }

        if (!enabled || targetKeyCode <= KEYCODE_UNKNOWN || keyCode != targetKeyCode) {
            return Action.PASS_THROUGH;
        }

        if (action == ACTION_DOWN) {
            if (repeatCount == 0 && !downActive) {
                downActive = true;
                downTimeMs = nowMs;
                holdTriggered = false;
                activePressId++;
                if (holdThresholdMs <= 0L) {
                    holdTriggered = true;
                    return Action.TRIGGER_CAMERA;
                }
                return Action.CONSUME_PENDING_HOLD;
            }
            return Action.CONSUME_ONLY;
        }

        if (action == ACTION_UP) {
            if (!downActive) {
                return Action.CONSUME_ONLY;
            }
            boolean alreadyTriggered = holdTriggered;
            long heldMs = Math.max(0L, nowMs - downTimeMs);
            clearPendingPress();
            if (alreadyTriggered || holdThresholdMs <= 0L) {
                return Action.CONSUME_ONLY;
            }
            if (heldMs >= holdThresholdMs && heldMs < HARD_UPPER_BOUND_MS) {
                return Action.TRIGGER_CAMERA;
            }
            return Action.REPLAY_SHORT_PRESS;
        }

        return Action.CONSUME_ONLY;
    }

    public synchronized Action onHoldTimeout(long nowMs) {
        return onHoldTimeoutForPress(activePressId, nowMs);
    }

    public synchronized Action onHoldTimeoutForPress(long pressId, long nowMs) {
        if (!enabled || !downActive || holdTriggered || pressId != activePressId) {
            return Action.CONSUME_ONLY;
        }
        long elapsed = Math.max(0L, nowMs - downTimeMs);
        if (elapsed >= holdThresholdMs && elapsed < HARD_UPPER_BOUND_MS) {
            holdTriggered = true;
            return Action.TRIGGER_CAMERA;
        }
        return Action.CONSUME_ONLY;
    }

    private void clearPendingPress() {
        downActive = false;
        downTimeMs = 0L;
        holdTriggered = false;
    }

    public static String formatKeyName(int keyCode) {
        switch (keyCode) {
            case KEYCODE_VOLUME_UP:
                return "VOL+ (Tăng âm lượng)";
            case KEYCODE_VOLUME_DOWN:
                return "VOL- (Giảm âm lượng)";
            case KEYCODE_MEDIA_PLAY_PAUSE:
                return "►‖ (Play / Pause)";
            case KEYCODE_MEDIA_PLAY:
                return "► (Play)";
            case KEYCODE_MEDIA_PAUSE:
                return "‖ (Pause)";
            case KEYCODE_MEDIA_NEXT:
                return "►| (Next / Qua bài)";
            case KEYCODE_MEDIA_PREVIOUS:
                return "|◄ (Prev / Lùi bài)";
            case KEYCODE_MEDIA_FAST_FORWARD:
                return "►► (Tua nhanh)";
            case KEYCODE_MEDIA_REWIND:
                return "◄◄ (Tua lại)";
            case KEYCODE_MEDIA_STOP:
                return "■ (Stop)";
            case KEYCODE_VOICE_ASSIST:
                return "🎙 Voice Assistant (Trợ lý giọng nói)";
            case KEYCODE_ASSIST:
                return "🎙 Assist / Tìm kiếm giọng nói";
            case KEYCODE_HEADSETHOOK:
                return "🎧 Headset Hook / Nút gọi";
            case KEYCODE_CAMERA:
                return "📷 Nút Camera";
            case KEYCODE_ENTER:
                return "OK / Enter";
            case KEYCODE_DPAD_CENTER:
                return "Nút giữa (DPAD Center)";
            case KEYCODE_UNKNOWN:
                return "Chưa gán phím";
            default:
                return "Phím #" + keyCode;
        }
    }
}

package com.tigeriq.camera;

import android.content.Context;
import android.content.SharedPreferences;

/**
 * Persists Bluetooth remote camera-popup shortcut preferences and diagnostics.
 */
public final class RemoteKeyPrefs {
    public static final String PREFS_NAME = "tigeriq_remote_shortcut";

    private static final String KEY_ENABLED = "enabled";
    private static final String KEY_CODE = "key_code";
    private static final String KEY_HOLD_MS = "hold_ms";
    private static final String KEY_PENDING_TOGGLE = "pending_remote_toggle";
    private static final String KEY_LAST_CODE = "last_key_code";
    private static final String KEY_LAST_DESC = "last_key_desc";
    private static final String KEY_LAST_TS = "last_key_ts";

    public static final class Preset {
        public final int keyCode;
        public final String shortLabel;

        public Preset(int keyCode, String shortLabel) {
            this.keyCode = keyCode;
            this.shortLabel = shortLabel;
        }
    }

    public static final Preset[] BUTTON_PRESETS = new Preset[] {
        new Preset(RemoteKeyShortcutEngine.KEYCODE_VOICE_ASSIST, "🎙 Voice"),
        new Preset(RemoteKeyShortcutEngine.KEYCODE_MEDIA_PLAY_PAUSE, "►‖ Play/Pause"),
        new Preset(RemoteKeyShortcutEngine.KEYCODE_MEDIA_NEXT, "►| Next"),
        new Preset(RemoteKeyShortcutEngine.KEYCODE_VOLUME_UP, "VOL+"),
        new Preset(RemoteKeyShortcutEngine.KEYCODE_VOLUME_DOWN, "VOL-"),
        new Preset(RemoteKeyShortcutEngine.KEYCODE_MEDIA_PREVIOUS, "|◄ Prev"),
        new Preset(RemoteKeyShortcutEngine.KEYCODE_ASSIST, "🎙 Assist"),
        new Preset(RemoteKeyShortcutEngine.KEYCODE_HEADSETHOOK, "🎧 Hook")
    };

    public static final long[] HOLD_PRESETS_MS = new long[] {
        600L,
        800L,
        1000L,
        1300L,
        1600L,
        0L
    };

    private RemoteKeyPrefs() {}

    public static SharedPreferences prefs(Context ctx) {
        return ctx.getApplicationContext().getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE);
    }

    public static boolean isEnabled(Context ctx) {
        return prefs(ctx).getBoolean(KEY_ENABLED, true);
    }

    public static void setEnabled(Context ctx, boolean enabled) {
        prefs(ctx).edit().putBoolean(KEY_ENABLED, enabled).apply();
    }

    public static int getKeyCode(Context ctx) {
        return prefs(ctx).getInt(KEY_CODE, RemoteKeyShortcutEngine.KEYCODE_VOICE_ASSIST);
    }

    public static void setKeyCode(Context ctx, int keyCode) {
        prefs(ctx).edit().putInt(KEY_CODE, keyCode).apply();
    }

    public static long getHoldMs(Context ctx) {
        long val = prefs(ctx).getLong(KEY_HOLD_MS, RemoteKeyShortcutEngine.DEFAULT_HOLD_MS);
        return RemoteKeyShortcutEngine.clampHoldMs(val);
    }

    public static void setHoldMs(Context ctx, long holdMs) {
        prefs(ctx).edit().putLong(KEY_HOLD_MS, RemoteKeyShortcutEngine.clampHoldMs(holdMs)).apply();
    }

    public static void setPendingToggle(Context ctx, boolean pending) {
        prefs(ctx).edit().putBoolean(KEY_PENDING_TOGGLE, pending).commit();
    }

    public static boolean consumePendingToggle(Context ctx) {
        SharedPreferences p = prefs(ctx);
        if (!p.getBoolean(KEY_PENDING_TOGGLE, false)) {
            return false;
        }
        p.edit().putBoolean(KEY_PENDING_TOGGLE, false).apply();
        return true;
    }

    public static void recordLastKey(Context ctx, int keyCode, String deviceName, long tsMs) {
        String safeDev = (deviceName == null || deviceName.trim().isEmpty()) ? "Bluetooth / HID" : deviceName.trim();
        String desc = RemoteKeyShortcutEngine.formatKeyName(keyCode) + " [" + safeDev + "]";
        prefs(ctx).edit()
            .putInt(KEY_LAST_CODE, keyCode)
            .putString(KEY_LAST_DESC, desc)
            .putLong(KEY_LAST_TS, tsMs)
            .apply();
    }

    public static String getLastKeySummary(Context ctx) {
        SharedPreferences p = prefs(ctx);
        int code = p.getInt(KEY_LAST_CODE, RemoteKeyShortcutEngine.KEYCODE_UNKNOWN);
        if (code <= 0) {
            return "Chưa ghi nhận phím nào — bấm nút trên Remote để kiểm tra.";
        }
        String desc = p.getString(KEY_LAST_DESC, "");
        return "Phím vừa nhận gần nhất: " + desc + " (code=" + code + ")";
    }

    public static String formatHoldLabel(long ms) {
        long clamped = RemoteKeyShortcutEngine.clampHoldMs(ms);
        if (clamped <= 0L) {
            return "Bấm 1 lần (0s)";
        }
        if (clamped == 800L) {
            return "0.8s (Khuyên dùng)";
        }
        return String.format(java.util.Locale.US, "%.1fs (< 2s)", clamped / 1000.0);
    }
}

package com.tigeriq.camera;

import android.app.ActivityOptions;
import android.content.Context;
import android.content.Intent;
import android.os.Build;
import android.os.Handler;
import android.os.Looper;
import android.widget.Toast;

/**
 * Handles stationary long-press (~0.65s) on FloatingCameraService's floating icon
 * to open the Bluetooth remote shortcut settings without disturbing normal short-tap or drag.
 */
public final class RemoteShortcutTouchHelper {
    private static final long LONG_PRESS_MS = 650L;
    private static final Handler MAIN_HANDLER = new Handler(Looper.getMainLooper());

    private static boolean pending = false;
    private static boolean triggered = false;
    private static Runnable activeRunnable = null;

    private RemoteShortcutTouchHelper() {}

    public static synchronized void onTouchDown(Context context, int displayId) {
        cancelLocked();
        if (context == null) {
            return;
        }
        final Context appCtx = context.getApplicationContext();
        final int targetDisplayId = displayId;
        pending = true;
        triggered = false;
        activeRunnable = new Runnable() {
            @Override
            public void run() {
                synchronized (RemoteShortcutTouchHelper.class) {
                    if (!pending || activeRunnable != this) {
                        return;
                    }
                    pending = false;
                    triggered = true;
                    activeRunnable = null;
                }
                launchConfigUi(appCtx, targetDisplayId);
            }
        };
        MAIN_HANDLER.postDelayed(activeRunnable, LONG_PRESS_MS);
    }

    public static synchronized void cancel() {
        cancelLocked();
    }

    public static synchronized boolean consumeIfLongPressed() {
        cancelLocked();
        boolean wasTriggered = triggered;
        triggered = false;
        return wasTriggered;
    }

    private static void cancelLocked() {
        pending = false;
        if (activeRunnable != null) {
            MAIN_HANDLER.removeCallbacks(activeRunnable);
            activeRunnable = null;
        }
    }

    public static void launchConfigUi(Context context, int displayId) {
        if (context == null) return;
        try {
            Intent intent = new Intent(context, RemoteShortcutConfigActivity.class);
            intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_SINGLE_TOP);
            if (Build.VERSION.SDK_INT >= 26 && displayId >= 0) {
                try {
                    ActivityOptions opts = ActivityOptions.makeBasic();
                    opts.setLaunchDisplayId(displayId);
                    context.startActivity(intent, opts.toBundle());
                    return;
                } catch (Throwable ignored) {
                }
            }
            context.startActivity(intent);
        } catch (Throwable t) {
            try {
                Toast.makeText(context, "Không mở được cài đặt Remote: " + t.getMessage(), Toast.LENGTH_SHORT).show();
            } catch (Throwable ignored) {
            }
        }
    }
}

