/**
 * Interactive configuration & key-learning dialog Activity for Bluetooth Remote -> Camera Popup.
 * Accessible by long-pressing FloatingCameraService's floating icon (~0.65s) or via Accessibility Settings.
 */
public class RemoteShortcutConfigActivity extends Activity {
    private boolean learning = false;
    private MediaSession learnMediaSession = null;

    private TextView accStatusBadge;
    private TextView accHintText;
    private Button accEnableBtn;
    private Switch enableSwitch;
    private TextView selectedKeyBadge;
    private TextView lastKeyText;
    private Button learnBtn;

    private final java.util.List<PresetChip> keyChips = new java.util.ArrayList<PresetChip>();
    private final java.util.List<HoldChip> holdChips = new java.util.ArrayList<HoldChip>();

    private static final class PresetChip {
        final int keyCode;
        final TextView view;

        PresetChip(int keyCode, TextView view) {
            this.keyCode = keyCode;
            this.view = view;
        }
    }

    private static final class HoldChip {
        final long holdMs;
        final TextView view;

        HoldChip(long holdMs, TextView view) {
            this.holdMs = holdMs;
            this.view = view;
        }
    }

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        requestWindowFeature(Window.FEATURE_NO_TITLE);
        setVolumeControlStream(AudioManager.USE_DEFAULT_STREAM_TYPE);

        ScrollView scroll = new ScrollView(this);
        scroll.setBackgroundColor(0xFF0B121C);
        scroll.setFillViewport(true);

        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        int pad = dp(16);
        root.setPadding(pad, pad, pad, dp(24));
        scroll.addView(root);

        // Header
        LinearLayout header = new LinearLayout(this);
        header.setOrientation(LinearLayout.HORIZONTAL);
        header.setGravity(Gravity.CENTER_VERTICAL);
        TextView title = new TextView(this);
        title.setText("Phím tắt Remote Bluetooth → Camera");
        title.setTextColor(0xFFF3F7FB);
        title.setTextSize(TypedValue.COMPLEX_UNIT_SP, 19);
        title.setTypeface(null, Typeface.BOLD);
        LinearLayout.LayoutParams titleLp = new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f);
        header.addView(title, titleLp);

        TextView closeBtn = makePill("✕ Đóng", 0xFF233042, 0xFFD9E3F0);
        closeBtn.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                finish();
            }
        });
        header.addView(closeBtn);
        root.addView(header);

        TextView sub = new TextView(this);
        sub.setText("Bấm nhanh giữ nguyên âm lượng/nhạc. Bấm giữ (< 2 giây) tương đương bấm icon Camera Popup.");
        sub.setTextColor(0xFF9FB0C4);
        sub.setTextSize(TypedValue.COMPLEX_UNIT_SP, 13);
        sub.setPadding(0, dp(4), 0, dp(14));
        root.addView(sub);

        // Card 1: Accessibility Permission
        LinearLayout accCard = makeCard();
        TextView accTitle = makeSectionTitle("1. Quyền Trợ Năng (chạy ngầm trên DeX & Vietmap)");
        accCard.addView(accTitle);

        accStatusBadge = new TextView(this);
        accStatusBadge.setTextSize(TypedValue.COMPLEX_UNIT_SP, 13);
        accStatusBadge.setTypeface(null, Typeface.BOLD);
        accStatusBadge.setPadding(dp(10), dp(6), dp(10), dp(6));
        accCard.addView(accStatusBadge);

        accHintText = new TextView(this);
        accHintText.setTextColor(0xFFBAC7D6);
        accHintText.setTextSize(TypedValue.COMPLEX_UNIT_SP, 12);
        accHintText.setPadding(0, dp(6), 0, dp(10));
        accCard.addView(accHintText);

        accEnableBtn = new Button(this);
        accEnableBtn.setText("Mở Cài đặt Trợ năng để Bật");
        accEnableBtn.setAllCaps(false);
        accEnableBtn.setTextColor(Color.WHITE);
        accEnableBtn.setBackground(roundRect(0xFF1F6FEB, 0xFF4493F8, dp(10)));
        accEnableBtn.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (RemoteKeyAccessibilityService.tryAutoEnableIfPermitted(RemoteShortcutConfigActivity.this)) {
                    Toast.makeText(RemoteShortcutConfigActivity.this, "Đã tự động bật Trợ năng UltraCar!", Toast.LENGTH_SHORT).show();
                    refreshUi();
                } else {
                    Toast.makeText(
                        RemoteShortcutConfigActivity.this,
                        "Chọn: Ứng dụng đã cài đặt -> UltraCar Phím tắt Remote -> BẬT",
                        Toast.LENGTH_LONG
                    ).show();
                    RemoteKeyAccessibilityService.openAccessibilitySettings(RemoteShortcutConfigActivity.this);
                }
            }
        });
        accCard.addView(accEnableBtn);
        root.addView(accCard);

        // Card 2: Enable Toggle + Button Picker + Learn Mode
        LinearLayout keyCard = makeCard();
        LinearLayout toggleRow = new LinearLayout(this);
        toggleRow.setOrientation(LinearLayout.HORIZONTAL);
        toggleRow.setGravity(Gravity.CENTER_VERTICAL);
        TextView swLabel = makeSectionTitle("2. Bật phím tắt Remote");
        swLabel.setPadding(0, 0, 0, 0);
        toggleRow.addView(swLabel, new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f));
        enableSwitch = new Switch(this);
        enableSwitch.setOnCheckedChangeListener(new CompoundButton.OnCheckedChangeListener() {
            @Override
            public void onCheckedChanged(CompoundButton buttonView, boolean isChecked) {
                RemoteKeyPrefs.setEnabled(RemoteShortcutConfigActivity.this, isChecked);
                RemoteKeyAccessibilityService.syncFromPrefs(RemoteShortcutConfigActivity.this);
            }
        });
        toggleRow.addView(enableSwitch);
        keyCard.addView(toggleRow);

        selectedKeyBadge = new TextView(this);
        selectedKeyBadge.setTextSize(TypedValue.COMPLEX_UNIT_SP, 15);
        selectedKeyBadge.setTypeface(null, Typeface.BOLD);
        selectedKeyBadge.setTextColor(0xFF7EE787);
        selectedKeyBadge.setPadding(0, dp(10), 0, dp(6));
        keyCard.addView(selectedKeyBadge);

        learnBtn = new Button(this);
        learnBtn.setAllCaps(false);
        learnBtn.setTextColor(Color.WHITE);
        learnBtn.setOnClickListener(new View.OnClickListener() {
