        lastKeyText = new TextView(this);
        lastKeyText.setTextColor(0xFF9FB0C4);
        lastKeyText.setTextSize(TypedValue.COMPLEX_UNIT_SP, 12);
        lastKeyText.setPadding(0, dp(8), 0, dp(8));
        keyCard.addView(lastKeyText);

        TextView presetHdr = new TextView(this);
        presetHdr.setText("Hoặc chọn nhanh nút trên Remote vô lăng:");
        presetHdr.setTextColor(0xFFD0DBE8);
        presetHdr.setTextSize(TypedValue.COMPLEX_UNIT_SP, 13);
        presetHdr.setPadding(0, dp(4), 0, dp(6));
        keyCard.addView(presetHdr);

        addChipGrid(keyCard, RemoteKeyPrefs.BUTTON_PRESETS);
        root.addView(keyCard);

        // Card 3: Hold threshold < 2s
        LinearLayout holdCard = makeCard();
        holdCard.addView(makeSectionTitle("3. Thời gian bấm giữ để bật Camera (< 2 giây)"));
        TextView holdNote = new TextView(this);
        holdNote.setText("Giữ đủ ngưỡng sẽ bật/tắt ngay Camera (không cần thả tay). Thả sớm hơn sẽ chỉnh âm lượng / nhạc như cũ.");
        holdNote.setTextColor(0xFF9FB0C4);
        holdNote.setTextSize(TypedValue.COMPLEX_UNIT_SP, 12);
        holdNote.setPadding(0, 0, 0, dp(8));
        holdCard.addView(holdNote);
        addHoldGrid(holdCard);
        root.addView(holdCard);

        // Card 4: Live Test Camera Toggle
        Button testBtn = new Button(this);
        testBtn.setText("📷 Bấm thử bật / tắt Camera Popup ngay");
        testBtn.setAllCaps(false);
        testBtn.setTextColor(Color.WHITE);
        testBtn.setBackground(roundRect(0xFF196C2E, 0xFF2EA043, dp(12)));
        testBtn.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                RemoteKeyAccessibilityService.invokeToggleCameraPopup(RemoteShortcutConfigActivity.this);
            }
        });
        LinearLayout.LayoutParams testLp = new LinearLayout.LayoutParams(
            LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
        testLp.topMargin = dp(4);
        root.addView(testBtn, testLp);

        setContentView(scroll);
        refreshUi();
    }

    @Override
    protected void onResume() {
        super.onResume();
        RemoteKeyAccessibilityService.setDiagnosticListener(new RemoteKeyAccessibilityService.KeyDiagnosticListener() {
            @Override
            public void onKeyObserved(int keyCode, String deviceName, boolean learned) {
                if (learned) {
                    onLearnedKey(keyCode);
                } else {
                    refreshUi();
                }
            }
        });
        refreshUi();
    }

    @Override
    protected void onPause() {
        super.onPause();
        RemoteKeyAccessibilityService.setDiagnosticListener(null);
        stopLearnMode();
    }

    @Override
    public boolean dispatchKeyEvent(KeyEvent event) {
        if (learning && event != null && event.getAction() == KeyEvent.ACTION_DOWN && event.getRepeatCount() == 0) {
            int code = event.getKeyCode();
            if (RemoteKeyShortcutEngine.isSafeMappableKey(code)) {
                RemoteKeyPrefs.recordLastKey(this, code, event.getDevice() != null ? event.getDevice().getName() : "Direct", System.currentTimeMillis());
                onLearnedKey(code);
                return true;
            }
        }
        return super.dispatchKeyEvent(event);
    }

    private void startLearnMode() {
        learning = true;
        RemoteKeyAccessibilityService.startLearn(this, new RemoteKeyShortcutEngine.LearnCallback() {
            @Override
            public void onKeyCaptured(int keyCode) {
                onLearnedKey(keyCode);
            }
        });
        try {
            releaseLearnSession();
            MediaSession ms = new MediaSession(this, "UltraCarLearn");
            ms.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS | MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);
            PlaybackState ps = new PlaybackState.Builder()
                .setActions(PlaybackState.ACTION_PLAY_PAUSE | PlaybackState.ACTION_PLAY | PlaybackState.ACTION_PAUSE
                    | PlaybackState.ACTION_SKIP_TO_NEXT | PlaybackState.ACTION_SKIP_TO_PREVIOUS | PlaybackState.ACTION_STOP)
                .setState(PlaybackState.STATE_PAUSED, 0L, 1.0f)
                .build();
            ms.setPlaybackState(ps);
            ms.setCallback(new MediaSession.Callback() {
                @Override
                public boolean onMediaButtonEvent(Intent mediaButtonIntent) {
                    if (!learning || mediaButtonIntent == null) return false;
                    KeyEvent ev = mediaButtonIntent.getParcelableExtra(Intent.EXTRA_KEY_EVENT);
                    if (ev != null && ev.getAction() == KeyEvent.ACTION_DOWN
                            && RemoteKeyShortcutEngine.isSafeMappableKey(ev.getKeyCode())) {
                        RemoteKeyPrefs.recordLastKey(
                            RemoteShortcutConfigActivity.this,
                            ev.getKeyCode(),
                            ev.getDevice() != null ? ev.getDevice().getName() : "MediaSession BT",
                            System.currentTimeMillis()
                        );
                        onLearnedKey(ev.getKeyCode());
                        return true;
                    }
                    return true;
                }
            });
            ms.setActive(true);
            learnMediaSession = ms;
        } catch (Throwable ignored) {
        }
        refreshUi();
    }

    private void stopLearnMode() {
        learning = false;
        RemoteKeyAccessibilityService.stopLearn(this);
        releaseLearnSession();
        refreshUi();
    }

    private void releaseLearnSession() {
        if (learnMediaSession != null) {
            try {
                learnMediaSession.setActive(false);
                learnMediaSession.release();
            } catch (Throwable ignored) {
            }
            learnMediaSession = null;
        }
    }

    private void onLearnedKey(int keyCode) {
        learning = false;
        releaseLearnSession();
        RemoteKeyPrefs.setKeyCode(this, keyCode);
        RemoteKeyPrefs.setEnabled(this, true);
        RemoteKeyAccessibilityService.syncFromPrefs(this);
        Toast.makeText(this, "Đã gán nút: " + RemoteKeyShortcutEngine.formatKeyName(keyCode), Toast.LENGTH_SHORT).show();
        refreshUi();
    }

    private void refreshUi() {
        boolean accOk = RemoteKeyAccessibilityService.isAccessibilityEnabled(this);
        if (accOk) {
            accStatusBadge.setText("● ĐANG BẬT — Hoạt động trên mọi màn hình (DeX / Vietmap)");
            accStatusBadge.setTextColor(0xFF7EE787);
            accStatusBadge.setBackground(roundRect(0xFF102A1B, 0xFF2EA043, dp(8)));
            accHintText.setText("Mẹo: giữ icon Camera nổi (~0.7s) bất cứ lúc nào để mở lại bảng cài đặt này.");
            accEnableBtn.setVisibility(View.GONE);
        } else {
            accStatusBadge.setText("○ CHƯA BẬT quyền Trợ năng UltraCar");
            accStatusBadge.setTextColor(0xFFFFD166);
            accStatusBadge.setBackground(roundRect(0xFF2C220D, 0xFFD29922, dp(8)));
            accHintText.setText("Bấm nút dưới → Chọn 'Ứng dụng đã cài đặt' → 'UltraCar — Phím tắt Remote BT' → BẬT.");
            accEnableBtn.setVisibility(View.VISIBLE);
        }

        enableSwitch.setChecked(RemoteKeyPrefs.isEnabled(this));
        int currentCode = RemoteKeyPrefs.getKeyCode(this);
        long currentHold = RemoteKeyPrefs.getHoldMs(this);
        selectedKeyBadge.setText("Nút đang gán: " + RemoteKeyShortcutEngine.formatKeyName(currentCode) + " (code=" + currentCode + ")");
        lastKeyText.setText(RemoteKeyPrefs.getLastKeySummary(this));

        if (learning) {
            learnBtn.setText("⏳ ĐANG CHỜ REMOTE... HÃY BẤM 1 NÚT TRÊN REMOTE (Bấm để huỷ)");
            learnBtn.setBackground(roundRect(0xFF9E4700, 0xFFF0883E, dp(10)));
        } else {
            learnBtn.setText("🎯 HỌC PHÍM TỪ REMOTE BLUETOOTH");
            learnBtn.setBackground(roundRect(0xFF213148, 0xFF4F6D93, dp(10)));
        }

        for (PresetChip chip : keyChips) {
            boolean sel = chip.keyCode == currentCode;
            chip.view.setBackground(roundRect(sel ? 0xFF1A4B2E : 0xFF1C2736, sel ? 0xFF3FB950 : 0xFF35455C, dp(8)));
            chip.view.setTextColor(sel ? 0xFFFFFFFF : 0xFFC9D5E3);
        }

        for (HoldChip chip : holdChips) {
            boolean sel = chip.holdMs == currentHold;
            chip.view.setBackground(roundRect(sel ? 0xFF183C6E : 0xFF1C2736, sel ? 0xFF58A6FF : 0xFF35455C, dp(8)));
            chip.view.setTextColor(sel ? 0xFFFFFFFF : 0xFFC9D5E3);
        }
    }

    private void addChipGrid(LinearLayout parent, RemoteKeyPrefs.Preset[] presets) {
        int cols = 4;
        for (int i = 0; i < presets.length; i += cols) {
            LinearLayout row = new LinearLayout(this);
            row.setOrientation(LinearLayout.HORIZONTAL);
            LinearLayout.LayoutParams rlp = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
            rlp.bottomMargin = dp(6);
            for (int j = 0; j < cols; j++) {
                int idx = i + j;
                if (idx >= presets.length) break;
                final RemoteKeyPrefs.Preset p = presets[idx];
                TextView tv = makeChip(p.shortLabel);
                tv.setOnClickListener(new View.OnClickListener() {
                    @Override
                    public void onClick(View v) {
                        learning = false;
                        releaseLearnSession();
                        RemoteKeyPrefs.setKeyCode(RemoteShortcutConfigActivity.this, p.keyCode);
                        RemoteKeyAccessibilityService.syncFromPrefs(RemoteShortcutConfigActivity.this);
                        refreshUi();
                    }
                });
                keyChips.add(new PresetChip(p.keyCode, tv));
                LinearLayout.LayoutParams clp = new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f);
                if (j > 0) clp.leftMargin = dp(6);
                row.addView(tv, clp);
            }
            parent.addView(row, rlp);
        }
    }

    private void addHoldGrid(LinearLayout parent) {
        long[] vals = RemoteKeyPrefs.HOLD_PRESETS_MS;
        int cols = 3;
        for (int i = 0; i < vals.length; i += cols) {
            LinearLayout row = new LinearLayout(this);
            row.setOrientation(LinearLayout.HORIZONTAL);
            LinearLayout.LayoutParams rlp = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
            rlp.bottomMargin = dp(6);
            for (int j = 0; j < cols; j++) {
                int idx = i + j;
                if (idx >= vals.length) break;
                final long ms = vals[idx];
                TextView tv = makeChip(RemoteKeyPrefs.formatHoldLabel(ms));
                tv.setOnClickListener(new View.OnClickListener() {
                    @Override
                    public void onClick(View v) {
                        RemoteKeyPrefs.setHoldMs(RemoteShortcutConfigActivity.this, ms);
                        RemoteKeyAccessibilityService.syncFromPrefs(RemoteShortcutConfigActivity.this);
                        refreshUi();
                    }
                });
                holdChips.add(new HoldChip(ms, tv));
                LinearLayout.LayoutParams clp = new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f);
                if (j > 0) clp.leftMargin = dp(6);
                row.addView(tv, clp);
            }
            parent.addView(row, rlp);
        }
    }

    private LinearLayout makeCard() {
        LinearLayout card = new LinearLayout(this);
        card.setOrientation(LinearLayout.VERTICAL);
        int p = dp(14);
        card.setPadding(p, p, p, p);
        card.setBackground(roundRect(0xFF141E2B, 0xFF28364A, dp(12)));
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(
            LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
        lp.bottomMargin = dp(12);
        card.setLayoutParams(lp);
        return card;
    }

    private TextView makeSectionTitle(String text) {
        TextView tv = new TextView(this);
        tv.setText(text);
        tv.setTextColor(0xFFEAF1F8);
        tv.setTextSize(TypedValue.COMPLEX_UNIT_SP, 15);
        tv.setTypeface(null, Typeface.BOLD);
        tv.setPadding(0, 0, 0, dp(8));
        return tv;
    }

    private TextView makeChip(String text) {
        TextView tv = new TextView(this);
        tv.setText(text);
        tv.setGravity(Gravity.CENTER);
        tv.setTextSize(TypedValue.COMPLEX_UNIT_SP, 12);
        tv.setTypeface(null, Typeface.BOLD);
        tv.setPadding(dp(6), dp(10), dp(6), dp(10));
        return tv;
    }

    private TextView makePill(String text, int bg, int fg) {
        TextView tv = new TextView(this);
        tv.setText(text);
        tv.setTextColor(fg);
        tv.setTextSize(TypedValue.COMPLEX_UNIT_SP, 13);
        tv.setTypeface(null, Typeface.BOLD);
        tv.setPadding(dp(12), dp(6), dp(12), dp(6));
        tv.setBackground(roundRect(bg, 0xFF3E4F66, dp(16)));
        return tv;
    }

    private GradientDrawable roundRect(int fill, int stroke, int radiusPx) {
        GradientDrawable gd = new GradientDrawable();
        gd.setColor(fill);
        gd.setCornerRadius(radiusPx);
        gd.setStroke(dp(1), stroke);
        return gd;
    }

    private int dp(int v) {
        return (int) (v * getResources().getDisplayMetrics().density + 0.5f);
    }
}

