            case KEYCODE_MEDIA_NEXT:
                return "►| (Next / Qua bài)";
            case KEYCODE_MEDIA_PREVIOUS:
                return "|◄ (Prev / Lùi bài)";
            case KEYCODE_MEDIA_FAST_FORWARD:
                return "►► (Tua nhanh)";
            case KEYCODE_MEDIA_REWIND:
                return "◄◄ (Tua lại)";
            case KEYCODE_MEDIA_STOP:
