FLOATING_CAR_REAR_ICON_JAVA = r"""package com.tigeriq.camera;

import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.Path;
import android.graphics.RectF;

public final class FloatingCarRearIcon {
    private FloatingCarRearIcon() {}

    public static void draw(Canvas canvas, Paint paint, int w, int h, boolean enabled) {
        if (canvas == null || paint == null || w <= 0 || h <= 0) return;
        float wf = (float) w;
        float hf = (float) h;
        float cx = wf * 0.5f;
        float cy = hf * 0.5f;
        float minDim = Math.min(wf, hf);
        float radius = (minDim * 0.5f) - Math.max(4.0f, minDim * 0.032f);

        // 1. Dark circular background (green tint when ON, neutral slate when OFF)
        paint.reset();
        paint.setAntiAlias(true);
        paint.setStyle(Paint.Style.FILL);
        paint.setColor(enabled ? 0xE60A2015 : 0xCC181C22);
        canvas.drawCircle(cx, cy, radius, paint);

        // 2. Outer status ring (ON = bright green, OFF = neutral gray)
        paint.setStyle(Paint.Style.STROKE);
        paint.setColor(enabled ? 0xFF00E676 : 0xCC78828E);
        paint.setStrokeWidth(Math.max(4.0f, minDim * (enabled ? 0.048f : 0.034f)));
        canvas.drawCircle(cx, cy, radius, paint);

        // 3. Rear car silhouette (shifted slightly left-down away from top-right R badge)
        float carCx = wf * 0.46f;
        float carTop = hf * 0.33f;
        float carBot = hf * 0.79f;
        float carH = carBot - carTop;
        float bodyW = wf * 0.52f;
        float roofW = wf * 0.34f;

        int bodyColor = enabled ? 0xFFFFFFFF : 0xCCA0A8B2;
        int darkTrim = enabled ? 0xFF0E2218 : 0xFF242A32;
        int tailOuter = enabled ? 0xFFFF2244 : 0xFF69707A;
        int tailCore = enabled ? 0xFFFF96A8 : 0xFF8A919B;

        paint.setStyle(Paint.Style.FILL);
        paint.setColor(bodyColor);

        // 3a. Rear wheels/tires
        float tireW = bodyW * 0.18f;
        float tireH = carH * 0.24f;
        float tireTop = carBot - tireH * 0.70f;
        float leftEdge = carCx - bodyW * 0.45f;
        float rightEdge = carCx + bodyW * 0.45f;
        float tr = minDim * 0.03f;
        canvas.drawRoundRect(new RectF(leftEdge, tireTop, leftEdge + tireW, carBot + carH * 0.03f), tr, tr, paint);
        canvas.drawRoundRect(new RectF(rightEdge - tireW, tireTop, rightEdge, carBot + carH * 0.03f), tr, tr, paint);

        float waistY = carTop + carH * 0.42f;

        // 3b. Side mirrors
        float mirrorH = carH * 0.11f;
        float mr = minDim * 0.02f;
        canvas.drawRoundRect(new RectF(carCx - bodyW * 0.54f, waistY - mirrorH * 0.5f, carCx - bodyW * 0.41f, waistY + mirrorH * 0.5f), mr, mr, paint);
        canvas.drawRoundRect(new RectF(carCx + bodyW * 0.41f, waistY - mirrorH * 0.5f, carCx + bodyW * 0.54f, waistY + mirrorH * 0.5f), mr, mr, paint);

        // 3c. Upper cabin + C-pillars
        Path cabin = new Path();
        cabin.moveTo(carCx - roofW * 0.44f, carTop);
        cabin.lineTo(carCx + roofW * 0.44f, carTop);
        cabin.lineTo(carCx + bodyW * 0.44f, waistY + carH * 0.04f);
        cabin.lineTo(carCx - bodyW * 0.44f, waistY + carH * 0.04f);
        cabin.close();
        canvas.drawPath(cabin, paint);

        // 3d. Dark rear windshield
        Path glass = new Path();
        float gwTop = roofW * 0.35f;
        float gwBot = bodyW * 0.33f;
        glass.moveTo(carCx - gwTop, carTop + carH * 0.09f);
        glass.lineTo(carCx + gwTop, carTop + carH * 0.09f);
        glass.lineTo(carCx + gwBot, waistY - carH * 0.02f);
        glass.lineTo(carCx - gwBot, waistY - carH * 0.02f);
        glass.close();
        paint.setColor(darkTrim);
        canvas.drawPath(glass, paint);

        // 3e. Lower wide tailgate / bumper
        float bodyBot = carBot - carH * 0.12f;
        paint.setColor(bodyColor);
        float brBody = minDim * 0.055f;
        canvas.drawRoundRect(new RectF(carCx - bodyW * 0.50f, waistY, carCx + bodyW * 0.50f, bodyBot), brBody, brBody, paint);

        // 3f. Rear taillights + V-shaped connecting LED light bar
        float lt = waistY + carH * 0.08f;
        float lb = waistY + carH * 0.21f;
        float lx = bodyW * 0.45f;
        float lr = minDim * 0.02f;
        paint.setColor(tailOuter);
        canvas.drawRoundRect(new RectF(carCx - lx, lt, carCx - bodyW * 0.16f, lb), lr, lr, paint);
        canvas.drawRoundRect(new RectF(carCx + bodyW * 0.16f, lt, carCx + lx, lb), lr, lr, paint);

        paint.setStyle(Paint.Style.STROKE);
        paint.setStrokeWidth(Math.max(2.0f, minDim * 0.018f));
        paint.setStrokeCap(Paint.Cap.ROUND);
        paint.setStrokeJoin(Paint.Join.ROUND);
        Path vBar = new Path();
        float midLightY = (lt + lb) * 0.5f;
        vBar.moveTo(carCx - bodyW * 0.17f, midLightY);
        vBar.lineTo(carCx, waistY + carH * 0.20f);
        vBar.lineTo(carCx + bodyW * 0.17f, midLightY);
        canvas.drawPath(vBar, paint);

        // Bright taillight inner core
        paint.setStyle(Paint.Style.FILL);
        paint.setColor(tailCore);
        float iy = (lb - lt) * 0.26f;
        float ixPad = minDim * 0.014f;
        float lrCore = minDim * 0.012f;
        canvas.drawRoundRect(new RectF(carCx - lx + ixPad, lt + iy, carCx - bodyW * 0.19f, lb - iy), lrCore, lrCore, paint);
        canvas.drawRoundRect(new RectF(carCx + bodyW * 0.19f, lt + iy, carCx + lx - ixPad, lb - iy), lrCore, lrCore, paint);

        // 3g. Rear license plate recess & lower bumper diffuser slit
        paint.setColor(darkTrim);
        canvas.drawRoundRect(new RectF(carCx - bodyW * 0.13f, waistY + carH * 0.21f, carCx + bodyW * 0.13f, waistY + carH * 0.33f), 2.0f, 2.0f, paint);
        canvas.drawRoundRect(new RectF(carCx - bodyW * 0.33f, bodyBot - carH * 0.09f, carCx + bodyW * 0.33f, bodyBot - carH * 0.02f), 2.0f, 2.0f, paint);

        // 4. Top-right 'R' badge
        float bx = wf * 0.76f;
        float by = hf * 0.23f;
        float br = minDim * 0.145f;
        paint.setColor(enabled ? 0xFFFF1744 : 0xDD4B5563);
        canvas.drawCircle(bx, by, br, paint);

        paint.setColor(enabled ? 0xFFFFFFFF : 0xDDD1D5DB);
        paint.setTextSize(minDim * 0.21f);
        paint.setFakeBoldText(true);
        paint.setTextAlign(Paint.Align.CENTER);
        Paint.FontMetrics fm = paint.getFontMetrics();
        float textY = by - (fm.ascent + fm.descent) * 0.5f;
        canvas.drawText("R", bx, textY, paint);
    }
}
"""

PARKING_GUIDE_FACTORY_JAVA = r"""package com.ultracar.dexsplit.ui;

import android.content.Context;
import android.view.View;
import android.view.ViewGroup;
import android.view.ViewParent;
import android.widget.FrameLayout;
import com.tigeriq.camera.NativeGuideWarpView;

public class ParkingGuideFactory {
    public ParkingGuideFactory() {}

    public static View createCameraContainer(Context context, View surfaceView) {
        if (context == null || surfaceView == null) {
            return surfaceView;
        }
        try {
            FrameLayout container = new FrameLayout(context);
            container.setLayoutParams(new ViewGroup.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.MATCH_PARENT
            ));
            container.addView(surfaceView);

            final NativeGuideWarpView overlay = new NativeGuideWarpView(context);
            overlay.setLayoutParams(new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.MATCH_PARENT
            ));
            surfaceView.addOnLayoutChangeListener(new View.OnLayoutChangeListener() {
                @Override
                public void onLayoutChange(View v, int l, int t, int r, int b,
                                           int ol, int ot, int or_, int ob) {
                    try {
                        if (v == null) return;
                        final int w = r - l;
                        final int h = b - t;
                        if (w <= 0 || h <= 0) return;
                        ViewParent vp = v.getParent();
                        final int pw = (vp instanceof View) ? ((View) vp).getWidth() : 0;
                        final int ph = (vp instanceof View) ? ((View) vp).getHeight() : 0;
                        final boolean fillParent = (l == 0 && t == 0 && pw > 0 && ph > 0 && w == pw && h == ph);
                        overlay.post(new Runnable() {
                            @Override
                            public void run() {
                                try {
                                    ViewGroup.LayoutParams raw = overlay.getLayoutParams();
                                    if (!(raw instanceof FrameLayout.LayoutParams)) {
                                        raw = new FrameLayout.LayoutParams(-1, -1);
                                        overlay.setLayoutParams(raw);
                                    }
                                    FrameLayout.LayoutParams lp = (FrameLayout.LayoutParams) raw;
                                    if (fillParent) {
                                        if (lp.width != -1 || lp.height != -1 || lp.leftMargin != 0 || lp.topMargin != 0) {
                                            lp.width = -1;
                                            lp.height = -1;
                                            lp.leftMargin = 0;
                                            lp.topMargin = 0;
                                            overlay.setLayoutParams(lp);
                                        }
                                    } else if (lp.width != w || lp.height != h || lp.leftMargin != l || lp.topMargin != t) {
                                        lp.width = w;
                                        lp.height = h;
                                        lp.leftMargin = l;
                                        lp.topMargin = t;
                                        overlay.setLayoutParams(lp);
                                    }
                                    overlay.postInvalidate();
                                } catch (Throwable ignored) {
                                }
                            }
                        });
                    } catch (Throwable ignored) {
                    }
                }
            });
            container.addView(overlay);
            return container;
        } catch (Throwable ignored) {
            return surfaceView;
        }
    }
}
"""

