            <intent-filter>
                <action android:name="android.accessibilityservice.AccessibilityService"/>
            </intent-filter>
            <meta-data android:name="android.accessibilityservice" android:resource="@xml/remote_key_accessibility_config"/>
        </service>
        <receiver android:exported="true" android:name="com.ultracar.dexsplit.data.ReverseGearReceiver">
            <intent-filter>
                <action android:name="com.tigeriq.dexsplit.ACTION_TOGGLE_CAMERA"/>
                <action android:name="com.tigeriq.dexsplit.ACTION_REVERSE_GEAR"/>""",
    )

    log("4. Bumping version to 1.2.13 (versionCode 359)...")
    p_yml = os.path.join(STAGE, "apktool.yml")
    replace_exact(p_yml, "  versionCode: '345'\n  versionName: 1.0.99", "  versionCode: '359'\n  versionName: 1.2.13")

    str_files = glob.glob(os.path.join(STAGE, "res", "values*", "strings.xml"))
    updated_strings = 0
    for sf in str_files:
        txt = open(sf, "r", encoding="utf-8").read()
        if "v1.0.99" in txt:
            replace_exact(sf, "v1.0.99", "v1.2.13")
            updated_strings += 1
    assert updated_strings == 7, f"Expected 7 strings.xml updates, got {updated_strings}"
    log(f"Updated v1.2.13 subtitle in {updated_strings} strings.xml files.")

    unsigned_apk = os.path.join(BUILD_ROOT, "UltraCar_v1.2.13_unsigned.apk")
    aligned_apk = os.path.join(BUILD_ROOT, "UltraCar_v1.2.13_aligned.apk")
    signed_apk = os.path.join(BUILD_ROOT, FINAL_APK_NAME)
    for f in (unsigned_apk, aligned_apk, signed_apk, signed_apk + ".idsig"):
        if os.path.exists(f):
            os.remove(f)

    log("5. Building APK via apktool...")
    with open(os.path.join(GOLDEN_V99, "smali", "pd0.smali"), "rb") as fp_g, open(os.path.join(STAGE, "smali", "pd0.smali"), "rb") as fp_s:
        assert fp_g.read() == fp_s.read(), "STAGE pd0.smali drifted from GOLDEN_V99!"
    run_cmd(["java", "-jar", APKTOOL_JAR, "b", "-j", "8", STAGE, "-o", unsigned_apk])

    log("6. Zipaligning APK...")
    run_cmd([ZIPALIGN, "-f", "-v", "4", unsigned_apk, aligned_apk])

    log("7. Signing & verifying APK with debug.keystore...")
    run_cmd([
        APKSIGNER, "sign",
        "--ks", KEYSTORE,
        "--ks-pass", "pass:android",
        "--key-pass", "pass:android",
        "--v2-signing-enabled", "true",
        "--v3-signing-enabled", "true",
        "--out", signed_apk,
        aligned_apk,
    ])
    run_cmd([APKSIGNER, "verify", "--verbose", signed_apk])
    with open(signed_apk, "rb") as f:
        sha = hashlib.sha256(f.read()).hexdigest()
    log(f"BUILT & SIGNED OK: {signed_apk} ({os.path.getsize(signed_apk):,} bytes, SHA256={sha})")
    return signed_apk


def publish_to_drive(signed_apk):
    assert os.path.isfile(signed_apk), f"Signed APK missing: {signed_apk}"
    log(f"8. Archiving old Drive APKs into {DRIVE_ARCHIVE} and publishing {FINAL_APK_NAME}...")
    os.makedirs(DRIVE_ARCHIVE, exist_ok=True)
    for item in os.listdir(DRIVE_ROOT):
        if item.lower().endswith(".apk"):
            src_old = os.path.join(DRIVE_ROOT, item)
            dst_old = os.path.join(DRIVE_ARCHIVE, item)
            if os.path.exists(dst_old):
                ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                dst_old = os.path.join(DRIVE_ARCHIVE, f"{os.path.splitext(item)[0]}_{ts}.apk")
            shutil.move(src_old, dst_old)
            log(f"Archived previous Drive APK: {src_old} -> {dst_old}")

    drive_final = os.path.join(DRIVE_ROOT, FINAL_APK_NAME)
    shutil.copy2(signed_apk, drive_final)
    remaining_apks = [f for f in os.listdir(DRIVE_ROOT) if f.lower().endswith(".apk")]
    assert remaining_apks == [FINAL_APK_NAME], f"Unexpected APKs in Drive root: {remaining_apks}"
    log(f"PUBLISHED OK: {drive_final} ({os.path.getsize(drive_final):,} bytes)")
    log(f"Drive root APK check PASSED: {remaining_apks}")


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--publish", action="store_true")
    args = parser.parse_args()
    signed_apk = os.path.join(BUILD_ROOT, FINAL_APK_NAME)
    if args.publish:
        publish_to_drive(signed_apk)
    else:
        build_apk()


if __name__ == "__main__":
    main()

